// ==========================================================================
// GENERIC COLUMN CONFIGURATION SYSTEM
// Per-user drag-and-drop column ordering + show/hide, Supabase-persisted
// ==========================================================================
const _colRegistry = {};   // tableId → { defs, render, prefs }
let _colPrefs = {};        // tableId → [{ id, visible }]  (loaded from Supabase)
let _colDragId = null;     // column id being dragged in any editor
let _colSaveTimer = null;  // debounce timer for Supabase writes

function _colRegister(tableId, defs, renderFn) {
  _colRegistry[tableId] = { defs, render: renderFn };
}

// Load all column prefs for the signed-in user (call once after login)
async function _colLoadAll() {
  try {
    const uid = currentProfile?.id;
    if (!uid) return;
    const rows = await _fetchAnon(`user_column_prefs?user_id=eq.${uid}&select=table_id,columns`);
    _colPrefs = {};
    (rows || []).forEach(r => { _colPrefs[r.table_id] = r.columns; });
    // Migrate punch list localStorage prefs into Supabase (one-time)
    const localPl = localStorage.getItem('cx-pl-cols');
    if (localPl && !_colPrefs['pl']) {
      try {
        _colPrefs['pl'] = JSON.parse(localPl);
        _colSave('pl');
        localStorage.removeItem('cx-pl-cols');
      } catch {}
    }
  } catch(e) { console.warn('[_colLoadAll] failed:', e.message); }
}

// Get resolved column list: saved order merged with any new defs
function _colGetActive(tableId) {
  const reg = _colRegistry[tableId];
  if (!reg) return [];
  const defs = reg.defs;
  const saved = _colPrefs[tableId];
  let cols;
  if (saved && saved.length) {
    const known = new Set(saved.map(c => c.id));
    cols = [
      ...saved.filter(c => defs.some(d => d.id === c.id)),
      ...defs.filter(d => !known.has(d.id)).map(d => ({ id: d.id, visible: d.default !== false })),
    ];
  } else {
    cols = defs.map(d => ({ id: d.id, visible: d.default !== false }));
  }
  return cols;
}

function _colGetVisible(tableId) {
  return _colGetActive(tableId).filter(c => c.visible);
}

// Debounced save to Supabase
function _colSave(tableId) {
  const uid = currentProfile?.id;
  if (!uid) return;
  clearTimeout(_colSaveTimer);
  _colSaveTimer = setTimeout(async () => {
    try {
      await _dbUpsert('user_column_prefs',
        [{ user_id: uid, table_id: tableId, columns: _colGetActive(tableId), updated_at: new Date().toISOString() }],
        'user_id,table_id');
    } catch(e) { console.warn('[_colSave]', e.message); }
  }, 600);
}

function _colToggle(tableId, colId, visible, refreshFn) {
  const cols = _colGetActive(tableId);
  const c = cols.find(x => x.id === colId);
  if (c) c.visible = visible;
  _colPrefs[tableId] = cols;
  _colSave(tableId);
  _colRefreshEditor(tableId, refreshFn);
}

function _colMove(tableId, colId, dir, refreshFn) {
  const cols = _colGetActive(tableId);
  const i = cols.findIndex(x => x.id === colId);
  const j = i + dir;
  if (j < 0 || j >= cols.length) return;
  [cols[i], cols[j]] = [cols[j], cols[i]];
  _colPrefs[tableId] = cols;
  _colSave(tableId);
  _colRefreshEditor(tableId, refreshFn);
}

function _colDragStart(e, colId) { _colDragId = colId; e.dataTransfer.effectAllowed = 'move'; }
function _colDragOver(e) { e.preventDefault(); e.dataTransfer.dropEffect = 'move'; }

function _colDrop(e, tableId, targetId, refreshFn) {
  e.preventDefault();
  if (!_colDragId || _colDragId === targetId) return;
  const cols = _colGetActive(tableId);
  const from = cols.findIndex(x => x.id === _colDragId);
  const to   = cols.findIndex(x => x.id === targetId);
  if (from < 0 || to < 0) { _colDragId = null; return; }
  const [moved] = cols.splice(from, 1);
  cols.splice(to, 0, moved);
  _colDragId = null;
  _colPrefs[tableId] = cols;
  _colSave(tableId);
  _colRefreshEditor(tableId, refreshFn);
}

function _colRefreshEditor(tableId, refreshFn) {
  const el = document.getElementById(`col-editor-${tableId}`);
  if (el) el.innerHTML = _colEditorListHTML(tableId, refreshFn);
  if (refreshFn) refreshFn();
}

function _colEditorListHTML(tableId, refreshFn) {
  const cols = _colGetActive(tableId);
  const reg = _colRegistry[tableId];
  if (!reg) return '';
  const fnName = refreshFn?.name || '';
  return cols.map((c, i) => {
    const def = reg.defs.find(d => d.id === c.id);
    if (!def) return '';
    return `<div draggable="true"
      ondragstart="_colDragStart(event,'${c.id}')"
      ondragover="_colDragOver(event)"
      ondrop="_colDrop(event,'${tableId}','${c.id}',${fnName || 'null'})"
      style="display:flex;align-items:center;gap:10px;padding:9px 12px;background:var(--white);border:1px solid var(--gray-200);border-radius:7px;margin-bottom:6px;cursor:grab;user-select:none;">
      <span style="color:var(--gray-400);font-size:18px;line-height:1;cursor:grab;">⠿</span>
      <label style="display:flex;align-items:center;gap:8px;flex:1;cursor:pointer;font-size:14px;font-weight:500;">
        <input type="checkbox" ${c.visible?'checked':''} onchange="_colToggle('${tableId}','${c.id}',this.checked,${fnName || 'null'})" style="width:15px;height:15px;cursor:pointer;">
        ${def.label}
      </label>
      <div style="display:flex;gap:4px;">
        <button onclick="_colMove('${tableId}','${c.id}',-1,${fnName || 'null'})" ${i===0?'disabled':''} style="font-size:13px;padding:2px 8px;border:1px solid var(--gray-200);border-radius:4px;background:var(--gray-50);cursor:pointer;">↑</button>
        <button onclick="_colMove('${tableId}','${c.id}',1,${fnName || 'null'})"  ${i===cols.length-1?'disabled':''} style="font-size:13px;padding:2px 8px;border:1px solid var(--gray-200);border-radius:4px;background:var(--gray-50);cursor:pointer;">↓</button>
      </div>
    </div>`;
  }).join('');
}

function _colOpenEditor(tableId, refreshFn) {
  const reg = _colRegistry[tableId];
  if (!reg) return;
  const fnName = refreshFn?.name || 'null';
  modal({
    title: 'Configure Columns',
    sub: 'Drag rows or use arrows to reorder · check to show / hide',
    size: 'small',
    body: `<div id="col-editor-${tableId}" style="padding:4px 0;">${_colEditorListHTML(tableId, refreshFn)}</div>`,
    footer: `
      <button class="form-secondary" onclick="_colReset('${tableId}',${fnName})">Reset Defaults</button>
      <button class="form-submit" onclick="closeModal()">Done</button>`,
  });
}

function _colReset(tableId, refreshFn) {
  const reg = _colRegistry[tableId];
  if (!reg) return;
  _colPrefs[tableId] = reg.defs.map(d => ({ id: d.id, visible: d.default !== false }));
  _colSave(tableId);
  _colRefreshEditor(tableId, refreshFn);
}

// Generate <th> cells for visible columns
function _colHeaders(tableId) {
  const vis = _colGetVisible(tableId);
  const reg = _colRegistry[tableId];
  if (!reg) return '';
  return vis.map(c => {
    const def = reg.defs.find(d => d.id === c.id);
    return `<th>${def ? def.label : c.id}</th>`;
  }).join('');
}

// Generate <td> cells for a row using the registered render function
function _colCells(tableId, row) {
  const vis = _colGetVisible(tableId);
  const reg = _colRegistry[tableId];
  if (!reg || !reg.render) return '';
  return vis.map(c => {
    const html  = reg.render(c.id, row);
    const def   = reg.defs && reg.defs.find(d => d.id === c.id);
    const label = (def && def.label) || c.id;
    // Tag each cell with its column label so the mobile card layout can show a
    // field label before the value. Desktop tables ignore data-label entirely.
    return html.replace('<td', `<td data-label="${escapeHtml(label)}"`);
  }).join('');
}

// ── escapeHtml + getLocationCode → extracted to format.js (P3-1 seam #2) ──

// ──────────────────────────────────────────────────────────────────────────────
// PAGE HERO HELPER — compact strip with optional inline KPI stats
// ──────────────────────────────────────────────────────────────────────────────
// Drop the returned HTML into a .page-hero's .container element. Pass `stats: []`
// (or omit) for pages without inline numbers — they still get the compact strip.
// stat tones: 'red' | 'amber' | 'blue' | 'good' | 'muted'
// role tones: 'admin' | 'field' | 'drawings'
// ──────────────────────────────────────────────────────────────────────────────
function renderPageHero(opts) {
  opts = opts || {};
  const { eyebrow, title, sub, role, stats } = opts;

  // CANONICAL heading grammar — every page renders the same three lines:
  //   .page-eyebrow  → the sidebar section (Overview/Testing/Field/Planning/
  //                    Project/Admin), mono + red dash
  //   .page-title    → the module name (one size everywhere)
  //   .page-sub      → one-line description (may carry HTML, e.g. counts)
  // plus an optional right-aligned .ph-stats strip.
  // `role` chips are retired: callers that still pass one get its label as
  // the eyebrow fallback so no page loses its wayfinding line.
  const eyebrowText = eyebrow || (role && role.label) || '';

  const statsHtml = (stats && stats.length) ? `
    <div class="ph-stats">
      ${stats.map(s => `
        <div class="ph-stat ${s.tone ? 'tone-' + s.tone : ''}">
          <span class="ph-stat-lbl">${escapeHtml(s.label || '')}</span>
          <span class="ph-stat-val">${s.value === null || s.value === undefined ? '—' : s.value}</span>
        </div>
      `).join('')}
    </div>` : '';

  return `
    <div class="page-hero-v3">
      <div class="ph-left">
        ${eyebrowText ? `<div class="page-eyebrow">${escapeHtml(eyebrowText)}</div>` : ''}
        <h1 class="page-title">${escapeHtml(title || '')}</h1>
        ${sub ? `<p class="page-sub">${sub}</p>` : ''}
      </div>
      ${statsHtml}
    </div>`;
}

// ==========================================
// DASHBOARD
// ==========================================
// Registry of live Chart.js instances — destroyed before each refresh to prevent canvas reuse errors
const _dashCharts = {};

function initDashboard() { refreshDashboard(); }

// Debounced trigger — call this from any mutation point to auto-refresh whichever
// weight-dependent view is currently visible. (Dashboard, Locations, Test Register
// all read weights through the shared lookups, so they need to re-render.)
function _tryRefreshDashboard() {
  clearTimeout(window._dashRefreshTimer);
  window._dashRefreshTimer = setTimeout(() => {
    if (document.getElementById('page-dashboard')?.classList.contains('active')) refreshDashboard();
    if (document.getElementById('page-locations')?.classList.contains('active')) initLocations();
    if (document.getElementById('page-test-register')?.classList.contains('active')
        && typeof renderTestRegister === 'function') renderTestRegister();
  }, 500);
}

function refreshDashboard() {
  if (!document.getElementById('page-dashboard')?.classList.contains('active')) return;

  document.getElementById('hero-update').textContent = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

  const ti    = _latestTI();
  const acts  = _amGetActivities();
  const punch = PUNCH_DB.filter(p => !p.is_deleted);

  const isPass = s => ['Pass','Passed','Complete'].includes(s);
  const isFail = s => ['Fail','Failed'].includes(s);

  const tiPass     = ti.filter(r => isPass(r.Status)).length;
  const tiFail     = ti.filter(r => isFail(r.Status)).length;
  const tiBlocked  = ti.filter(r => r.Status === 'Blocked').length;
  const tiInProg   = ti.filter(r => r.Status === 'In Progress').length;
  const tiNa       = ti.filter(r => r.Status === 'Not Applicable').length;
  const tiFuture   = ti.filter(r => r.Status === 'Future Test').length;
  const tiTotal    = ti.length;

  // Weighted percentages — honours weights set in Admin → Weights
  const ws         = _wgtStat(ti);
  const complete   = tiPass + tiNa; // raw count for meta text
  const overallPct = ws.totalW > 0   ? Math.round((ws.completeW / ws.totalW) * 100) : 0;
  const tested     = tiPass + tiFail + tiBlocked;
  const passRate   = ws.testedW > 0  ? Math.round((ws.passW    / ws.testedW) * 100) : 0;

  const actClosed  = acts.filter(a => _amComputeStatus(a) === 'Closed').length;
  const actPartial = acts.filter(a => _amComputeStatus(a) === 'Partial Completion').length;
  const actOpen    = acts.filter(a => _amComputeStatus(a) === 'Open').length;

  const punchOpen    = punch.filter(p => p.status !== 'closed').length;
  const punchHigh    = punch.filter(p => p.priority === 'high' && p.status !== 'closed').length;
  const punchOverdue = punch.filter(p => p.due_date && new Date(p.due_date) < new Date() && p.status !== 'closed').length;

  const _hasCustomWeights = _anyCustomWeights(ti);
  const _wNote = _hasCustomWeights ? ` <span style="font-size:10px;font-weight:600;color:var(--gray-400);letter-spacing:.03em;">WEIGHTED</span>` : '';

  // Overall progress KPI: by default shows static-register progress. Admin
  // toggle on the card flips it to combined (static + dynamic instances).
  _dashRenderOverallProgress({ overallPct, complete, tiTotal, _wNote });

  document.getElementById('kpi-passrate').textContent = passRate + '%';
  document.getElementById('kpi-passrate-meta').innerHTML = `<b>${tiPass}</b> passed / <b>${tiFail + tiBlocked}</b> failed or blocked${_wNote}`;

  document.getElementById('kpi-activities').textContent = acts.length;
  document.getElementById('kpi-activities-meta').innerHTML = `<b class="good-text">${actClosed}</b> closed · <b>${actOpen}</b> open${actPartial ? ` · <b style="color:#d97706;">${actPartial}</b> partial` : ''}`;

  document.getElementById('kpi-punch').textContent = punchOpen;
  document.getElementById('kpi-punch-meta').innerHTML = `<b>${punchHigh}</b> high priority · ${punchOverdue} overdue`;

  document.getElementById('metric-row').innerHTML = `
    <div class="metric-tile">
      <div class="metric-tile-label"><span class="metric-tile-icon" style="background:${COLORS.good}"></span>Tests Passed</div>
      <div class="metric-tile-value good">${tiPass.toLocaleString()}</div>
    </div>
    <div class="metric-tile">
      <div class="metric-tile-label"><span class="metric-tile-icon" style="background:${COLORS.bad}"></span>Tests Failed</div>
      <div class="metric-tile-value bad">${tiFail}</div>
    </div>
    <div class="metric-tile">
      <div class="metric-tile-label"><span class="metric-tile-icon" style="background:${COLORS.warn}"></span>Blocked</div>
      <div class="metric-tile-value warn">${tiBlocked}</div>
    </div>
    <div class="metric-tile">
      <div class="metric-tile-label"><span class="metric-tile-icon" style="background:${COLORS.info}"></span>In Progress</div>
      <div class="metric-tile-value">${tiInProg}</div>
    </div>
    <div class="metric-tile">
      <div class="metric-tile-label"><span class="metric-tile-icon" style="background:#7c3aed"></span>Future Test</div>
      <div class="metric-tile-value" style="color:#7c3aed;">${tiFuture}</div>
    </div>
    <div class="metric-tile">
      <div class="metric-tile-label"><span class="metric-tile-icon" style="background:${COLORS.bad}"></span>Punch Overdue</div>
      <div class="metric-tile-value bad">${punchOverdue}</div>
    </div>
  `;

  renderPhaseGrid();
  renderLIStatusChart();
  renderSubsysRateChart();
  renderFutureTestChart();
  renderPunchTradeChart();
  renderLocationChart();
  renderFailedList();
  renderHighPunchList();
  _dashRenderActiveView();
}

function renderPhaseGrid() {
  const acts    = _amGetActivities();
  const phases  = [...new Set(acts.map(a => a.phase).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));
  const grid    = document.getElementById('phase-grid');
  const allTI   = _latestTI();
  // Build weight lookups once for the whole loop instead of per phase.
  const _aw  = _buildActivityWeightLookup();
  const _tcw = _buildTestCaseWeightLookup();
  let html = '';
  phases.forEach(phase => {
    const items   = acts.filter(a => a.phase === phase);
    const closed  = items.filter(a => _amComputeStatus(a) === 'Closed').length;
    const future  = items.filter(a => _amComputeStatus(a) === 'Future Test').length;
    const open    = items.length - closed - future;
    const total   = items.length;
    // Weighted test-case completion for this phase (activity × test-case)
    const phaseTI = allTI.filter(r => r.Phase === phase);
    const ws      = _wgtStat(phaseTI, _aw, _tcw);
    const pct     = ws.totalW > 0 ? Math.round((ws.completeW / ws.totalW) * 100) : 0;
    html += `
      <div class="phase-card">
        <div class="phase-card-num">${escapeHtml(phase)}</div>
        <div class="phase-progress-display">
          <div class="phase-progress-pct">${pct}%</div>
          <div class="phase-progress-meta">weighted complete · <b>${closed}</b>/${total} activities closed</div>
        </div>
        <div class="phase-bar"><div class="phase-bar-fill" style="width:0%" data-target="${pct}%"></div></div>
        <div class="phase-stats">
          <div class="phase-stat-item"><div class="phase-stat-label">Closed</div><div class="phase-stat-value good">${closed}</div></div>
          <div class="phase-stat-item"><div class="phase-stat-label">Open</div><div class="phase-stat-value">${open}</div></div>
          <div class="phase-stat-item"><div class="phase-stat-label">Future</div><div class="phase-stat-value" style="color:#7c3aed;">${future}</div></div>
        </div>
      </div>
    `;
  });
  grid.innerHTML = html || '<p style="color:var(--gray-500);padding:24px;">No activity data yet.</p>';
  setTimeout(() => {
    document.querySelectorAll('.phase-bar-fill[data-target]').forEach(el => { el.style.width = el.dataset.target; });
  }, 200);
}

function renderLIStatusChart() {
  const ctx = document.getElementById('chart-li-status');
  const ti = _latestTI();
  // Use raw test-case counts for chart segments — weights only drive the % KPIs,
  // not the slice sizes. Showing weighted sums here would produce values like "2775.5
  // Passed" when an activity weight is set to 1000, which is misleading.
  const passed   = ti.filter(r => ['Pass','Passed','Complete'].includes(r.Status)).length;
  const failed   = ti.filter(r => ['Fail','Failed'].includes(r.Status)).length;
  const blocked  = ti.filter(r => r.Status === 'Blocked').length;
  const inprog   = ti.filter(r => r.Status === 'In Progress').length;
  const future   = ti.filter(r => r.Status === 'Future Test').length;
  const na       = ti.filter(r => r.Status === 'Not Applicable').length;
  const notStart = ti.filter(r => !r.Status || r.Status === 'Not Started').length;
  if (_dashCharts.liStatus) _dashCharts.liStatus.destroy();
  _dashCharts.liStatus = new Chart(ctx, {
    type: 'doughnut',
    data: {
      labels: ['Passed','Failed','Blocked','In Progress','Not Started','Future Test','N/A'],
      datasets: [{
        data: [passed, failed, blocked, inprog, notStart, future, na],
        backgroundColor: [COLORS.good, COLORS.bad, COLORS.warn, COLORS.info, COLORS.gray, '#7c3aed', '#9ca3af'],
        borderWidth: 0, hoverOffset: 8,
      }]
    },
    options: {
      responsive: true, maintainAspectRatio: false, cutout: '65%',
      plugins: {
        legend: { position: 'right', labels: { boxWidth: 10, boxHeight: 10, padding: 12, font: { size: 11 }, usePointStyle: true, pointStyle: 'circle' } },
        tooltip: {
          backgroundColor: COLORS.black, padding: 12,
          callbacks: { label: ctx => { const tot = ctx.dataset.data.reduce((a,b)=>a+b,0); return ` ${ctx.parsed.toLocaleString()} (${tot ? ((ctx.parsed/tot)*100).toFixed(1) : 0}%)`; } }
        }
      }
    }
  });
}

function renderSubsysRateChart() {
  const ctx = document.getElementById('chart-subsys-rate');
  const ti  = _latestTI();
  const groups  = {};
  const awMap   = _buildActivityWeightLookup();
  const tcwMap  = _buildTestCaseWeightLookup();
  ti.forEach(r => {
    const sub = r.Subsystem; if (!sub) return;
    const tcW  = _tcWeightFor(r, tcwMap);
    const actW = _actWeightFor(r, awMap);
    const wgt  = tcW * actW;
    if (!groups[sub]) groups[sub] = { passed: 0, failed: 0, total: 0 };
    if (['Pass','Passed','Complete'].includes(r.Status)) groups[sub].passed += wgt;
    if (['Fail','Failed'].includes(r.Status)) groups[sub].failed += wgt;
    groups[sub].total += wgt;
  });
  const sorted = Object.entries(groups).filter(([_,v])=>v.total>=1).sort((a,b)=>b[1].total-a[1].total).slice(0,12);
  // Normalise to 0–100% per subsystem so high activity weights don't blow up the axis.
  // Each bar segment shows the weighted share of that status within the subsystem.
  const pct = (v, tot) => tot > 0 ? Math.round(v / tot * 100) : 0;
  if (_dashCharts.subsys) _dashCharts.subsys.destroy();
  _dashCharts.subsys = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: sorted.map(s=>s[0]),
      datasets: [
        { label:'Passed', data:sorted.map(s=>pct(s[1].passed, s[1].total)), backgroundColor:COLORS.good, stack:'st' },
        { label:'Failed', data:sorted.map(s=>pct(s[1].failed, s[1].total)), backgroundColor:COLORS.bad,  stack:'st' },
        { label:'Other',  data:sorted.map(s=>pct(s[1].total-s[1].passed-s[1].failed, s[1].total)), backgroundColor:COLORS.grayLight, stack:'st' },
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: false, indexAxis: 'y',
      scales: {
        x: { stacked:true, min:0, max:100, grid:{color:'#f4f4f4'}, ticks:{ callback: v => v+'%' } },
        y: { stacked:true, grid:{display:false} },
      },
      plugins: {
        legend: { position:'top', align:'end', labels:{ boxWidth:10, boxHeight:10, padding:12, usePointStyle:true, pointStyle:'rect' } },
        tooltip: {
          backgroundColor: COLORS.black, padding: 12,
          callbacks: { label: ctx => ` ${ctx.dataset.label}: ${ctx.parsed.x}%` }
        }
      }
    }
  });
}

function renderFutureTestChart() {
  const ctx = document.getElementById('chart-future-reason');
  if (!ctx) return;
  const futureTI = _latestTI().filter(r => r.Status === 'Future Test');
  const counts = {};
  futureTI.forEach(r => {
    const raw = r.FutureTestReason || '';
    const cat = (raw.split('|')[0].trim()) || 'Unspecified';
    counts[cat] = (counts[cat] || 0) + 1;
  });
  const sorted = Object.entries(counts).sort((a,b)=>b[1]-a[1]);
  if (!sorted.length) { const wrap = ctx.closest('.chart-card'); if (wrap) wrap.style.display='none'; return; }
  const wrap2 = ctx.closest('.chart-card'); if (wrap2) wrap2.style.display='';
  const palette = ['#7c3aed','#6d28d9','#a78bfa','#4c1d95','#8b5cf6','#c4b5fd'];
  if (_dashCharts.futureReason) _dashCharts.futureReason.destroy();
  _dashCharts.futureReason = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: sorted.map(x=>x[0]),
      datasets: [{ label:'Test Cases', data:sorted.map(x=>x[1]), backgroundColor:sorted.map((_,i)=>palette[i%palette.length]), borderRadius:4 }]
    },
    options: {
      responsive:true, maintainAspectRatio:false,
      scales: { x:{grid:{display:false}}, y:{grid:{color:'#f4f4f4'},beginAtZero:true,ticks:{precision:0}} },
      plugins: { legend:{display:false}, tooltip:{backgroundColor:COLORS.black,padding:12} }
    }
  });
}

function renderPunchTradeChart() {
  const ctx   = document.getElementById('chart-punch-trade');
  const punch = PUNCH_DB.filter(p => !p.is_deleted && p.status !== 'closed');
  const counts = {};
  punch.forEach(p => { const key = p.subsystem || p.phase || 'Unassigned'; counts[key] = (counts[key]||0)+1; });
  const sorted = Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,10);
  if (_dashCharts.punch) _dashCharts.punch.destroy();
  _dashCharts.punch = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: sorted.map(x=>x[0]),
      datasets: [{ label:'Open Items', data:sorted.map(x=>x[1]), backgroundColor:COLORS.red, borderRadius:4 }]
    },
    options: {
      responsive:true, maintainAspectRatio:false,
      scales: { x:{grid:{display:false}}, y:{grid:{color:'#f4f4f4'},beginAtZero:true,ticks:{precision:0}} },
      plugins: { legend:{display:false}, tooltip:{backgroundColor:COLORS.black,padding:12} }
    }
  });
}

function renderLocationChart() {
  const ctx  = document.getElementById('chart-loc');
  const acts = _amGetActivities();
  const counts = {};
  acts.forEach(a => { const l = a.location; if (!l) return; counts[l]=(counts[l]||0)+1; });
  const sorted = Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,15);
  if (_dashCharts.loc) _dashCharts.loc.destroy();
  _dashCharts.loc = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: sorted.map(x=>x[0]),
      datasets: [{ label:'Activities', data:sorted.map(x=>x[1]), backgroundColor:COLORS.black, borderRadius:4 }]
    },
    options: {
      responsive:true, maintainAspectRatio:false, indexAxis:'y',
      scales: { x:{grid:{color:'#f4f4f4'},beginAtZero:true,ticks:{precision:0}}, y:{grid:{display:false}} },
      plugins: { legend:{display:false}, tooltip:{backgroundColor:COLORS.black,padding:12} }
    }
  });
}

function renderFailedList() {
  const failed = _latestTI().filter(r => ['Fail','Failed'].includes(r.Status)).slice(0,5);
  const list   = document.getElementById('failed-list');
  list.innerHTML = failed.length ? failed.map(r => `
    <div class="mini-list-item">
      <div class="mini-list-dot dot-bad"></div>
      <div class="mini-list-content">
        <div class="mini-list-title">${escapeHtml(r.TestName || r.TestCaseCode || '—')}</div>
        <div class="mini-list-meta"><b>${escapeHtml(r.Subsystem||'—')}</b> · ${escapeHtml(r.Location||'—')} · ${escapeHtml(r.Activity||'—')}</div>
        ${r.FailedReason ? `<div style="font-size:11px;color:#dc2626;margin-top:2px;">${escapeHtml(r.FailedReason)}</div>` : ''}
      </div>
    </div>`).join('')
  : `<div style="color:var(--gray-500);font-size:12px;padding:8px 0;">No failed tests ${icon('sparkles')}</div>`;
}

function renderHighPunchList() {
  const high = PUNCH_DB.filter(p => !p.is_deleted && p.priority === 'high' && p.status !== 'closed').slice(0,5);
  const list = document.getElementById('high-punch-list');
  list.innerHTML = high.length ? high.map(p => `
    <div class="mini-list-item">
      <div class="mini-list-dot dot-bad"></div>
      <div class="mini-list-content">
        <div class="mini-list-title">${escapeHtml(p.title || '—')}</div>
        <div class="mini-list-meta"><b>${escapeHtml(p.subsystem || p.phase || '—')}</b> · ${escapeHtml(p.location || '—')}</div>
      </div>
    </div>`).join('')
  : `<div style="color:var(--gray-500);font-size:12px;padding:8px 0;">No high-priority items</div>`;
}

// ==========================================
// DASHBOARD VIEW SELECTOR (Overview / Velocity / Productivity / Schedule / Quality)
// ==========================================
let _dashView    = 'overview';
let _dashProgress = null;   // cached kpi_test_progress rows

function _dashSet(id, val) { const el = document.getElementById(id); if (el) el.textContent = val; }

function setDashView(view) {
  _dashView = view;
  document.querySelectorAll('.dash-view').forEach(el => {
    el.style.display = (el.id === 'dash-view-' + view) ? '' : 'none';
  });
  document.querySelectorAll('.dash-view-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.dview === view);
  });
  _dashRenderActiveView();
}

function _dashRenderActiveView() {
  if      (_dashView === 'velocity')     _dashRenderVelocity();
  else if (_dashView === 'productivity') _dashRenderProductivity();
  else if (_dashView === 'schedule')     _dashRenderSchedule();
  else if (_dashView === 'quality')      _dashRenderQuality();
}

// Per-test completion timing + rework counts, reconstructed server-side from
// db_change_log (view: kpi_test_progress). Cached for the session; pass force
// to refetch after edits.
async function _dashGetProgress(force = false) {
  if (_dashProgress && !force) return _dashProgress;
  try { _dashProgress = await _fetchAnon('kpi_test_progress?select=*'); }
  catch (e) { console.warn('[kpi] progress fetch failed:', e.message); _dashProgress = []; }
  return _dashProgress;
}

const _DAY_MS = 86400000;
function _dashWeekStart(d) { const t = new Date(d); const off = (t.getDay() + 6) % 7; t.setHours(0,0,0,0); t.setDate(t.getDate() - off); return t; }
function _dashFmtDay(d)  { return new Date(d).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }); }

// ── Velocity & Throughput ──────────────────────────────────────────────────
async function _dashRenderVelocity() {
  const rows  = await _dashGetProgress();
  const now   = Date.now();
  const scope = rows.filter(r => r.status !== 'Not Applicable').length;
  const doneDates = rows.filter(r => r.effective_completed_at)
                        .map(r => new Date(r.effective_completed_at).getTime())
                        .sort((a, b) => a - b);
  const doneN  = doneDates.length;
  const within = days => doneDates.filter(t => (now - t) <= days * _DAY_MS).length;

  let avgWk = 0;
  if (doneN) { const spanDays = Math.max(1, (now - doneDates[0]) / _DAY_MS); avgWk = doneN / (spanDays / 7); }
  const remaining = scope - doneN;
  let eta = '—';
  if (remaining <= 0)      eta = 'Complete';
  else if (avgWk > 0)      eta = new Date(now + (remaining / avgWk) * 7 * _DAY_MS).toLocaleDateString('en-US', { month: 'short', year: 'numeric' });

  const tested  = rows.filter(r => r.pass_events > 0 || r.fail_events > 0);
  const cleanFP = rows.filter(r => r.pass_events > 0 && r.fail_events === 0).length;
  const fpy     = tested.length ? Math.round(cleanFP / tested.length * 100) : null;
  const rework  = tested.length ? Math.round(rows.filter(r => r.fail_events > 0).length / tested.length * 100) : null;

  _dashSet('vel-7d', within(7));
  _dashSet('vel-30d', within(30));
  _dashSet('vel-avgwk', Math.round(avgWk));
  _dashSet('vel-eta', eta);
  _dashSet('vel-fpy', fpy == null ? 'n/a' : fpy + '%');
  _dashSet('vel-rework', rework == null ? 'n/a' : rework + '%');

  // Burn-up: cumulative completed by day, with a flat total-scope reference line
  const byDay = {};
  doneDates.forEach(t => { const k = new Date(t).toISOString().slice(0, 10); byDay[k] = (byDay[k] || 0) + 1; });
  const days = Object.keys(byDay).sort();
  let cum = 0;
  const cumData = days.map(k => (cum += byDay[k]));
  const burnCtx = document.getElementById('chart-burnup');
  if (burnCtx) {
    if (_dashCharts.burnup) _dashCharts.burnup.destroy();
    _dashCharts.burnup = new Chart(burnCtx, {
      type: 'line',
      data: {
        labels: days.map(_dashFmtDay),
        datasets: [
          { label: 'Completed (cumulative)', data: cumData, borderColor: COLORS.good, backgroundColor: 'rgba(0,135,90,.12)', fill: true, tension: .25, pointRadius: 2 },
          { label: 'Total scope', data: days.map(() => scope), borderColor: COLORS.grayLight, borderDash: [6, 4], pointRadius: 0, fill: false },
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        scales: { x: { grid: { display: false } }, y: { beginAtZero: true, grid: { color: '#f4f4f4' } } },
        plugins: { legend: { position: 'top', align: 'end', labels: { boxWidth: 10, boxHeight: 10, usePointStyle: true, pointStyle: 'line' } }, tooltip: { backgroundColor: COLORS.black, padding: 12 } }
      }
    });
  }

  // Weekly throughput
  const byWeek = {};
  doneDates.forEach(t => { const k = _dashWeekStart(t).toISOString().slice(0, 10); byWeek[k] = (byWeek[k] || 0) + 1; });
  const weeks = Object.keys(byWeek).sort();
  const tpCtx = document.getElementById('chart-throughput');
  if (tpCtx) {
    if (_dashCharts.throughput) _dashCharts.throughput.destroy();
    _dashCharts.throughput = new Chart(tpCtx, {
      type: 'bar',
      data: { labels: weeks.map(w => 'wk of ' + _dashFmtDay(w)), datasets: [{ label: 'Tests completed', data: weeks.map(w => byWeek[w]), backgroundColor: COLORS.info, borderRadius: 4 }] },
      options: { responsive: true, maintainAspectRatio: false, scales: { x: { grid: { display: false } }, y: { beginAtZero: true, grid: { color: '#f4f4f4' }, ticks: { precision: 0 } } }, plugins: { legend: { display: false }, tooltip: { backgroundColor: COLORS.black, padding: 12 } } }
    });
  }
}

// ── Field Productivity (delay_log) ─────────────────────────────────────────
async function _dashRenderProductivity() {
  let logs = [];
  try { logs = await _fetchAnon('delay_log?select=*&order=log_date.asc'); }
  catch (e) { console.warn('[kpi] delay_log fetch failed:', e.message); }
  const empty = document.getElementById('prod-empty');
  const num = v => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };

  if (!logs.length) {
    if (empty) empty.style.display = '';
    ['prod-days','prod-ttd','prod-idle','prod-delaydays','prod-passrate'].forEach(id => _dashSet(id, '—'));
    ['delayCause','dailyTests'].forEach(k => { if (_dashCharts[k]) { _dashCharts[k].destroy(); _dashCharts[k] = null; } });
    return;
  }
  if (empty) empty.style.display = 'none';

  const fieldDays  = new Set(logs.map(l => l.log_date).filter(Boolean)).size;
  const totLogged  = logs.reduce((s, l) => s + num(l.total_tests_logged), 0);
  const totPassed  = logs.reduce((s, l) => s + num(l.total_passed), 0);
  const testerDays = logs.reduce((s, l) => s + Math.max(1, num(l.number_of_testers)), 0);
  const totIdle    = logs.reduce((s, l) => s + num(l.idle_hours), 0);
  const delayDays  = new Set(logs.filter(l => l.delay_occurred === 'Yes').map(l => l.log_date)).size;

  _dashSet('prod-days', fieldDays);
  _dashSet('prod-ttd', testerDays ? (totLogged / testerDays).toFixed(1) : '—');
  _dashSet('prod-idle', totIdle.toLocaleString());
  _dashSet('prod-delaydays', delayDays);
  _dashSet('prod-passrate', totLogged ? Math.round(totPassed / totLogged * 100) + '%' : '—');

  // Idle hours by delay cause
  const causes = {};
  logs.filter(l => l.delay_occurred === 'Yes').forEach(l => {
    const k = l.delay_category || 'Uncategorised';
    causes[k] = (causes[k] || 0) + num(l.idle_hours);
  });
  const cSorted = Object.entries(causes).sort((a, b) => b[1] - a[1]);
  const dcCtx = document.getElementById('chart-delay-cause');
  if (dcCtx) {
    if (_dashCharts.delayCause) _dashCharts.delayCause.destroy();
    _dashCharts.delayCause = new Chart(dcCtx, {
      type: 'bar',
      data: { labels: cSorted.map(c => c[0]), datasets: [{ label: 'Idle hours', data: cSorted.map(c => c[1]), backgroundColor: COLORS.warn, borderRadius: 4 }] },
      options: { responsive: true, maintainAspectRatio: false, indexAxis: 'y', scales: { x: { beginAtZero: true, grid: { color: '#f4f4f4' } }, y: { grid: { display: false } } }, plugins: { legend: { display: false }, tooltip: { backgroundColor: COLORS.black, padding: 12 } } }
    });
  }

  // Daily tests logged vs passed
  const byDate = {};
  logs.forEach(l => {
    if (!l.log_date) return;
    if (!byDate[l.log_date]) byDate[l.log_date] = { logged: 0, passed: 0 };
    byDate[l.log_date].logged += num(l.total_tests_logged);
    byDate[l.log_date].passed += num(l.total_passed);
  });
  const dates = Object.keys(byDate).sort();
  const dtCtx = document.getElementById('chart-daily-tests');
  if (dtCtx) {
    if (_dashCharts.dailyTests) _dashCharts.dailyTests.destroy();
    _dashCharts.dailyTests = new Chart(dtCtx, {
      type: 'bar',
      data: {
        labels: dates.map(_dashFmtDay),
        datasets: [
          { label: 'Logged', data: dates.map(d => byDate[d].logged), backgroundColor: COLORS.grayLight, borderRadius: 4 },
          { label: 'Passed', data: dates.map(d => byDate[d].passed), backgroundColor: COLORS.good, borderRadius: 4 },
        ]
      },
      options: { responsive: true, maintainAspectRatio: false, scales: { x: { grid: { display: false } }, y: { beginAtZero: true, grid: { color: '#f4f4f4' }, ticks: { precision: 0 } } }, plugins: { legend: { position: 'top', align: 'end', labels: { boxWidth: 10, boxHeight: 10, usePointStyle: true, pointStyle: 'rect' } }, tooltip: { backgroundColor: COLORS.black, padding: 12 } } }
    });
  }
}

// ── Schedule Adherence (planned_date vs actual) ─────────────────────────────
async function _dashRenderSchedule() {
  const rows    = await _dashGetProgress();
  const planned = rows.filter(r => r.planned_date);
  const empty   = document.getElementById('sch-empty');
  if (empty) empty.style.display = planned.length ? 'none' : '';

  const now = new Date(); now.setHours(0, 0, 0, 0);
  const endOf = d => { const t = new Date(d); t.setHours(23, 59, 59, 999); return t; };
  const completedPlanned = planned.filter(r => r.effective_completed_at);
  const onTime = completedPlanned.filter(r => new Date(r.effective_completed_at) <= endOf(r.planned_date)).length;
  _dashSet('sch-ontime', completedPlanned.length ? Math.round(onTime / completedPlanned.length * 100) + '%' : 'n/a');
  _dashSet('sch-behind', planned.filter(r => !r.effective_completed_at && new Date(r.planned_date) < now).length);
  _dashSet('sch-due14', planned.filter(r => { if (r.effective_completed_at) return false; const p = new Date(r.planned_date); return p >= now && (p - now) <= 14 * _DAY_MS; }).length);
  const lastPlanned = planned.length ? new Date(Math.max(...planned.map(r => +new Date(r.planned_date)))) : null;
  _dashSet('sch-finish', lastPlanned ? lastPlanned.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '—');

  // S-curve: cumulative planned (by planned_date) vs actual (by effective completion)
  const plannedDays = {}, actualDays = {};
  planned.forEach(r => { const k = String(r.planned_date).slice(0, 10); plannedDays[k] = (plannedDays[k] || 0) + 1; });
  rows.filter(r => r.effective_completed_at).forEach(r => { const k = new Date(r.effective_completed_at).toISOString().slice(0, 10); actualDays[k] = (actualDays[k] || 0) + 1; });
  const allDays = [...new Set([...Object.keys(plannedDays), ...Object.keys(actualDays)])].sort();
  let cp = 0, ca = 0;
  const plannedCum = [], actualCum = [];
  const todayKey = now.toISOString().slice(0, 10);
  allDays.forEach(k => {
    cp += plannedDays[k] || 0; ca += actualDays[k] || 0;
    plannedCum.push(cp);
    actualCum.push(k <= todayKey ? ca : null); // actual only up to today
  });
  const scCtx = document.getElementById('chart-scurve');
  if (scCtx) {
    if (_dashCharts.scurve) _dashCharts.scurve.destroy();
    _dashCharts.scurve = new Chart(scCtx, {
      type: 'line',
      data: {
        labels: allDays.map(_dashFmtDay),
        datasets: [
          { label: 'Planned (cumulative)', data: plannedCum, borderColor: COLORS.info, borderDash: [6, 4], pointRadius: 0, tension: .2, fill: false },
          { label: 'Actual (cumulative)',  data: actualCum,  borderColor: COLORS.good, backgroundColor: 'rgba(0,135,90,.12)', pointRadius: 0, tension: .2, fill: true, spanGaps: false },
        ]
      },
      options: { responsive: true, maintainAspectRatio: false, scales: { x: { grid: { display: false }, ticks: { maxTicksLimit: 12 } }, y: { beginAtZero: true, grid: { color: '#f4f4f4' } } }, plugins: { legend: { position: 'top', align: 'end', labels: { boxWidth: 10, boxHeight: 10, usePointStyle: true, pointStyle: 'line' } }, tooltip: { backgroundColor: COLORS.black, padding: 12 } } }
    });
  }

  // Upcoming planned tests (next 30d) by subsystem — sourced from the lookahead
  // schedule (planning_events), not test-case planned_date. Each scheduled
  // activity in the window is counted once and grouped by subsystem: the linked
  // test item's subsystem when present, otherwise the activity's trade (lookahead
  // trade codes — DCS, IXL, … — match the test register's subsystem codes).
  await loadPlanningData();
  const subsysByTestId = new Map();
  (_latestTI() || []).forEach(t => { if (t.TestID != null) subsysByTestId.set(String(t.TestID), t.Subsystem || ''); });
  const actById = new Map((PLANNING_ACTIVITIES || []).map(a => [a.id, a]));
  const upcoming = {};
  const seenActivities = new Set();
  (PLANNING_EVENTS || []).forEach(e => {
    if (!e.event_date || e.status === 'cancelled') return;
    const d = new Date(e.event_date); d.setHours(0, 0, 0, 0);
    if (d < now || (d - now) > 30 * _DAY_MS) return;
    const act = e.planning_activity_id ? actById.get(e.planning_activity_id) : null;
    if (act && act.deleted_at) return; // ignore soft-deleted activities
    const testId = e.test_item_id || (act && act.linked_test_item_id) || null;
    // Dedup so an activity scheduled across multiple days counts once.
    const key = testId ? `t:${testId}` : (e.planning_activity_id ? `a:${e.planning_activity_id}` : `e:${e.id}`);
    if (seenActivities.has(key)) return;
    seenActivities.add(key);
    const k = (testId && subsysByTestId.get(String(testId))) || (act && act.trade) || 'Unassigned';
    upcoming[k] = (upcoming[k] || 0) + 1;
  });
  const uSorted = Object.entries(upcoming).sort((a, b) => b[1] - a[1]).slice(0, 12);
  const upCtx = document.getElementById('chart-upcoming');
  if (upCtx) {
    if (_dashCharts.upcoming) _dashCharts.upcoming.destroy();
    _dashCharts.upcoming = new Chart(upCtx, {
      type: 'bar',
      data: { labels: uSorted.map(u => u[0]), datasets: [{ label: 'Tests due', data: uSorted.map(u => u[1]), backgroundColor: COLORS.info, borderRadius: 4 }] },
      options: { responsive: true, maintainAspectRatio: false, scales: { x: { grid: { display: false } }, y: { beginAtZero: true, grid: { color: '#f4f4f4' }, ticks: { precision: 0 } } }, plugins: { legend: { display: false }, tooltip: { backgroundColor: COLORS.black, padding: 12 } } }
    });
  }
}

// ── Quality & Issues (punch / rma / fails) ──────────────────────────────────
function _dashRenderQuality() {
  const punch    = (typeof PUNCH_DB !== 'undefined' ? PUNCH_DB : []).filter(p => !p.is_deleted);
  const openP    = punch.filter(p => p.status !== 'closed');
  const now      = Date.now();
  const overdueP = openP.filter(p => p.due_date && new Date(p.due_date).getTime() < now);
  const ages     = openP.map(p => p.created_at ? (now - new Date(p.created_at).getTime()) / _DAY_MS : NaN).filter(n => !isNaN(n));
  const avgAge   = ages.length ? Math.round(ages.reduce((a, b) => a + b, 0) / ages.length) : 0;

  const rmas     = (typeof RMAS !== 'undefined' ? RMAS : []);
  const openR    = rmas.filter(r => (r.status || '').toLowerCase() !== 'closed');
  const overdueR = openR.filter(r => r.due_date && new Date(r.due_date).getTime() < now);

  const fails    = _latestTI().filter(r => ['Fail', 'Failed'].includes(r.Status));

  _dashSet('ql-punch-open', openP.length);
  _dashSet('ql-punch-overdue', overdueP.length);
  _dashSet('ql-punch-age', avgAge ? avgAge + 'd' : '—');
  _dashSet('ql-rma-open', openR.length);
  _dashSet('ql-rma-overdue', overdueR.length);
  _dashSet('ql-fails', fails.length);

  // Punch aging buckets
  const buckets = { '0–7d': 0, '8–30d': 0, '31–90d': 0, '90d+': 0 };
  openP.forEach(p => {
    if (!p.created_at) return;
    const d = (now - new Date(p.created_at).getTime()) / _DAY_MS;
    if (d <= 7) buckets['0–7d']++; else if (d <= 30) buckets['8–30d']++; else if (d <= 90) buckets['31–90d']++; else buckets['90d+']++;
  });
  const paCtx = document.getElementById('chart-punch-age');
  if (paCtx) {
    if (_dashCharts.punchAge) _dashCharts.punchAge.destroy();
    _dashCharts.punchAge = new Chart(paCtx, {
      type: 'bar',
      data: { labels: Object.keys(buckets), datasets: [{ label: 'Open items', data: Object.values(buckets), backgroundColor: [COLORS.good, COLORS.info, COLORS.warn, COLORS.bad], borderRadius: 4 }] },
      options: { responsive: true, maintainAspectRatio: false, scales: { x: { grid: { display: false } }, y: { beginAtZero: true, grid: { color: '#f4f4f4' }, ticks: { precision: 0 } } }, plugins: { legend: { display: false }, tooltip: { backgroundColor: COLORS.black, padding: 12 } } }
    });
  }

  // Failed tests by subsystem
  const fSub = {};
  fails.forEach(r => { const k = r.Subsystem || 'Unassigned'; fSub[k] = (fSub[k] || 0) + 1; });
  const fSorted = Object.entries(fSub).sort((a, b) => b[1] - a[1]).slice(0, 12);
  const fsCtx = document.getElementById('chart-fail-subsys');
  if (fsCtx) {
    if (_dashCharts.failSubsys) _dashCharts.failSubsys.destroy();
    _dashCharts.failSubsys = new Chart(fsCtx, {
      type: 'bar',
      data: { labels: fSorted.map(f => f[0]), datasets: [{ label: 'Failed tests', data: fSorted.map(f => f[1]), backgroundColor: COLORS.bad, borderRadius: 4 }] },
      options: { responsive: true, maintainAspectRatio: false, indexAxis: 'y', scales: { x: { beginAtZero: true, grid: { color: '#f4f4f4' }, ticks: { precision: 0 } }, y: { grid: { display: false } } }, plugins: { legend: { display: false }, tooltip: { backgroundColor: COLORS.black, padding: 12 } } }
    });
  }
}

// ==========================================
// SAT ACTIVITIES PAGE
// ==========================================
let apSort = { col: null, asc: false };


// Build the Activities table rows from the REAL test register (grouped TI +
// activity_records), reusing the activity-manager derivation + status/completion
// math. Replaces the old data.js actionPlans demo source.
let _apBound = false;
function _apBuildRows() {
  if (typeof _amGetActivities !== 'function') return [];
  const tcw = (typeof _buildTestCaseWeightLookup === 'function') ? _buildTestCaseWeightLookup() : null;
  return _amGetActivities().map(act => {
    const comp = _amComputeCompletion(act, tcw);
    const first = act.items[0] || {};
    return {
      Name:               act.activity,
      Description:         act.activity,
      'SubSystem-':        act.subsystem,
      Phase:              act.phase,
      'Test Level':       first.TestLevel || first['Test Level'] || '—',
      Location:           act.location,
      Progress:           comp.pct + '%',
      Status:             _amComputeStatus(act),
      'Test Report CDRL': act.testReport || '',
      _comp:              comp,
    };
  });
}
function initActivities() {
  AP = _apBuildRows();
  document.getElementById('ap-summary').textContent = `${AP.length} SAT activities across ${new Set(AP.map(r => r.Location).filter(Boolean)).size} locations`;

  // Build filter options
  const statuses = [...new Set(AP.map(r => r.Status).filter(Boolean))].sort();
  const subsys = [...new Set(AP.map(r => r['SubSystem-']).filter(Boolean))].sort();
  const phases = [...new Set(AP.map(r => String(r.Phase)).filter(p => p && p !== 'undefined'))].sort();
  const locs = [...new Set(AP.map(r => r.Location).filter(Boolean))].sort();

  populateSelect('ap-status-filter', 'All statuses', statuses);
  populateSelect('ap-subsys-filter', 'All subsystems', subsys);
  populateSelect('ap-phase-filter', 'All phases', phases.map(p => `Phase ${p}`));
  populateSelect('ap-location-filter', 'All locations', locs);

  if (!_apBound) {
    _apBound = true;
  ['ap-search','ap-status-filter','ap-subsys-filter'].forEach(id => {
    document.getElementById(id).addEventListener('input', renderAPTable);
  });
  document.getElementById('ap-phase-filter').addEventListener('input', () => { _apCascadeLocation(); renderAPTable(); });
  document.getElementById('ap-location-filter').addEventListener('input', renderAPTable);

  // Sort handlers
  document.querySelectorAll('#ap-table th[data-sort]').forEach(th => {
    th.addEventListener('click', () => {
      const col = th.dataset.sort;
      if (apSort.col === col) apSort.asc = !apSort.asc;
      else { apSort.col = col; apSort.asc = true; }
      renderAPTable();
    });
  });

  }
  renderAPTable();
}

function _apCascadeLocation() {
  const subsysF = document.getElementById('ap-subsys-filter').value;
  const phaseF  = document.getElementById('ap-phase-filter').value.replace('Phase ', '');
  const avail   = AP.filter(r => (!subsysF || r['SubSystem-'] === subsysF) && (!phaseF || String(r.Phase).trim() === phaseF));
  const locs    = [...new Set(avail.map(r => r.Location).filter(Boolean))].sort();
  const cur     = document.getElementById('ap-location-filter').value;
  populateSelect('ap-location-filter', 'All locations', locs);
  if (!locs.includes(cur)) document.getElementById('ap-location-filter').value = '';
}

function clearAPFilters() {
  ['ap-search','ap-status-filter','ap-subsys-filter','ap-phase-filter','ap-location-filter'].forEach(id => document.getElementById(id).value = '');
  renderAPTable();
}

function populateSelect(id, allLabel, options) {
  const el = document.getElementById(id);
  el.innerHTML = `<option value="">${allLabel}</option>` + options.map(o => `<option value="${escapeHtml(o)}">${escapeHtml(o)}</option>`).join('');
}

function renderAPTable() {
  const search = document.getElementById('ap-search').value.toLowerCase();
  const statusF = document.getElementById('ap-status-filter').value;
  const subsysF = document.getElementById('ap-subsys-filter').value;
  const phaseF = document.getElementById('ap-phase-filter').value.replace('Phase ', '');
  const locF = document.getElementById('ap-location-filter').value;

  let data = AP.filter(r =>
    (!search || (r.Name && r.Name.toLowerCase().includes(search)) || (r.Description && r.Description.toLowerCase().includes(search))) &&
    (!statusF || r.Status === statusF) &&
    (!subsysF || r['SubSystem-'] === subsysF) &&
    (!phaseF || String(r.Phase).trim() === phaseF) &&
    (!locF || r.Location === locF)
  );

  // Sort
  if (apSort.col) {
    data = [...data].sort((a, b) => {
      const av = a[apSort.col] || '';
      const bv = b[apSort.col] || '';
      const cmp = av.toString().localeCompare(bv.toString(), undefined, { numeric: true });
      return apSort.asc ? cmp : -cmp;
    });
  }

  const tbody = document.getElementById('ap-body');
  tbody.innerHTML = data.map(r => `
    <tr>
      <td>
        <span class="cell-name">${escapeHtml(r.Name)}</span>
        ${r['Test Report CDRL'] ? `<span class="cell-sub">CDRL ${escapeHtml(r['Test Report CDRL'])}</span>` : ''}
      </td>
      <td><span class="tag">${escapeHtml(r['SubSystem-'] || '—')}</span></td>
      <td><span class="tag tag-phase">${escapeHtml(String(r.Phase || '—').trim())}</span></td>
      <td>${escapeHtml(r['Test Level'] || '—')}</td>
      <td>${escapeHtml(r.Location || '—')}</td>
      <td class="cell-mono">${escapeHtml(r.Progress || '—')}</td>
      <td>${getStatusBadge(r.Status)}</td>
    </tr>
  `).join('');

  document.getElementById('ap-count').textContent = `Showing ${data.length} of ${AP.length} activities`;

  // Update sort indicator
  document.querySelectorAll('#ap-table th').forEach(th => th.classList.remove('sorted','sorted-asc'));
  if (apSort.col) {
    const th = document.querySelector(`#ap-table th[data-sort="${apSort.col}"]`);
    if (th) th.classList.add('sorted', apSort.asc ? 'sorted-asc' : '');
  }
}

// ==========================================
// TEST CASES PAGE  (sourced from TI / test_items)
// ==========================================
let liSort = { col: null, asc: false };
let _liKpiFilter = ''; // 'pass' | 'inprog' | 'blocked' | 'notstarted' | ''

// ── LI column definitions ──
_colRegister('li', [
  { id: 'activity',  label: 'Activity',  sortKey: 'Activity',  default: true },
  { id: 'testname',  label: 'Test Name', sortKey: 'TestName',  default: true },
  { id: 'subsystem', label: 'Subsystem', sortKey: 'Subsystem', default: true },
  { id: 'phase',     label: 'Phase',     sortKey: 'Phase',     default: true },
  { id: 'location',  label: 'Location',  sortKey: 'Location',  default: true },
  { id: 'status',    label: 'Status',    sortKey: 'Status',    default: true },
  { id: 'scope',     label: 'Scope',     sortKey: 'ScopeType', default: true },
  { id: 'testcode',  label: 'Test Code', sortKey: 'TestCaseCode', default: false },
  { id: 'weight',    label: 'Weight',    sortKey: 'Weight',    default: false },
], function _liRenderCell(colId, r) {
  switch (colId) {
    case 'activity':  return `<td><span class="cell-sub" style="font-size:12px">${escapeHtml(r.Activity || '—')}</span></td>`;
    case 'testname':  return `<td>${r.TestCaseCode ? `<span class="cell-mono" style="font-size:11px;color:var(--gray-500);margin-right:6px;">${escapeHtml(r.TestCaseCode)}</span>` : ''}<span class="cell-name">${escapeHtml(r.TestName || '—')}</span></td>`;
    case 'subsystem': return `<td><span class="tag">${escapeHtml(r.Subsystem || '—')}</span></td>`;
    case 'phase':     return `<td><span class="tag tag-phase">${escapeHtml(String(r.Phase || '—').trim())}</span></td>`;
    case 'location':  return `<td>${escapeHtml(r.Location || '—')}</td>`;
    case 'status':    return `<td>${getStatusBadge(r.Status)}</td>`;
    case 'scope':     return _dtRenderScopeCell(r);
    case 'testcode':  return `<td style="font-family:var(--font-mono,monospace);font-size:12px;">${escapeHtml(r.TestCaseCode || '—')}</td>`;
    case 'weight':    return `<td style="font-size:12px;text-align:center;">${r.Weight ?? '—'}</td>`;
    default: return '<td>—</td>';
  }
});

function _liSetKpiFilter(key) {
  _liKpiFilter = (_liKpiFilter === key) ? '' : key; // toggle off if already active
  renderLITable();
}

function _liMatchKpiStatus(r) {
  if (!_liKpiFilter) return true;
  if (_liKpiFilter === 'pass')       return ['Pass','Passed','Complete','Not Applicable'].includes(r.Status);
  if (_liKpiFilter === 'inprog')     return r.Status === 'In Progress';
  if (_liKpiFilter === 'blocked')    return r.Status === 'Fail' || r.Status === 'Failed' || r.Status === 'Blocked';
  if (_liKpiFilter === 'notstarted') return !r.Status || r.Status === 'Not Started';
  return true;
}

function initLineItems() {
  // TI is already subsystem-filtered at login for non-admin users
  const base = TI;
  const userSubsys = currentRoleUser?.subsystem || null;
  const isAdmin = currentRoleUser?.role === 'admin';

  document.getElementById('li-summary').textContent =
    `${base.length.toLocaleString()} test cases${userSubsys && !isAdmin ? ` · ${userSubsys}` : ' across all subsystems'}`;

  // Populate filter dropdowns from the (already-scoped) TI data
  const subsystems = [...new Set(base.map(r => r.Subsystem).filter(Boolean))].sort();
  const phases     = [...new Set(base.map(r => String(r.Phase || '')).filter(Boolean))].sort((a,b) => a.localeCompare(b, undefined, {numeric:true}));
  const locs       = [...new Set(base.map(r => r.Location).filter(Boolean))].sort();
  const activities = [...new Set(base.map(r => r.Activity).filter(Boolean))].sort();
  const statuses   = [...new Set(base.map(r => r.Status).filter(Boolean))].sort();

  populateSelect('li-subsys-filter',   'All subsystems', subsystems);
  populateSelect('li-phase-filter',    'All phases',     phases);
  populateSelect('li-location-filter', 'All locations',  locs);
  populateSelect('li-activity-filter', 'All activities', activities);
  populateSelect('li-status-filter',   'All statuses',   statuses);

  // For non-admin with a subsystem, pre-select their subsystem and hide the filter
  const subsysEl = document.getElementById('li-subsys-filter');
  if (userSubsys && !isAdmin) {
    subsysEl.value = userSubsys;
    subsysEl.style.display = 'none';
  } else {
    subsysEl.style.display = '';
  }

  document.getElementById('li-subsys-filter')?.addEventListener('input', () => { _liCascade('subsystem'); renderLITable(); });
  document.getElementById('li-phase-filter')?.addEventListener('input',  () => { _liCascade('phase');    renderLITable(); });
  document.getElementById('li-location-filter')?.addEventListener('input',() => { _liCascade('location'); renderLITable(); });
  document.getElementById('li-activity-filter')?.addEventListener('input', renderLITable);
  document.getElementById('li-status-filter')?.addEventListener('input',   renderLITable);
  document.getElementById('li-search')?.addEventListener('input',           renderLITable);

  renderLITable();
}

// changedKey: 'subsystem' | 'phase' | 'location' — the filter the user just changed.
// Every other dependent dropdown is re-populated based on the current combined selection.
function _liCascade(changedKey) {
  const isAdmin    = currentRoleUser?.role === 'admin';
  const userSubsys = currentRoleUser?.subsystem || null;

  const curSub = document.getElementById('li-subsys-filter').value;
  const curPh  = document.getElementById('li-phase-filter').value;
  const curLoc = document.getElementById('li-location-filter').value;
  const curAct = document.getElementById('li-activity-filter').value;

  // Re-populate subsystem options (skip if it was the changed key, or if locked for non-admin)
  if (changedKey !== 'subsystem' && (isAdmin || !userSubsys)) {
    const subs = [...new Set(TI.filter(r =>
      (!curPh  || r.Phase    === curPh) &&
      (!curLoc || r.Location === curLoc)
    ).map(r => r.Subsystem).filter(Boolean))].sort();
    populateSelect('li-subsys-filter', 'All subsystems', subs);
    document.getElementById('li-subsys-filter').value = subs.includes(curSub) ? curSub : '';
  }

  // Re-populate phase options (skip if it was the changed key)
  if (changedKey !== 'phase') {
    const fSub = document.getElementById('li-subsys-filter').value;
    const phases = [...new Set(TI.filter(r =>
      (!fSub   || r.Subsystem === fSub) &&
      (!curLoc || r.Location  === curLoc)
    ).map(r => r.Phase).filter(Boolean))].sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
    populateSelect('li-phase-filter', 'All phases', phases);
    document.getElementById('li-phase-filter').value = phases.includes(curPh) ? curPh : '';
  }

  // Re-populate location options (skip if it was the changed key)
  if (changedKey !== 'location') {
    const fSub   = document.getElementById('li-subsys-filter').value;
    const fPhase = document.getElementById('li-phase-filter').value;
    const locs = [...new Set(TI.filter(r =>
      (!fSub   || r.Subsystem === fSub) &&
      (!fPhase || r.Phase     === fPhase)
    ).map(r => r.Location).filter(Boolean))].sort();
    populateSelect('li-location-filter', 'All locations', locs);
    document.getElementById('li-location-filter').value = locs.includes(curLoc) ? curLoc : '';
  }

  // Always re-populate activity options from all active filters
  const fSub   = document.getElementById('li-subsys-filter').value;
  const fPhase = document.getElementById('li-phase-filter').value;
  const fLoc   = document.getElementById('li-location-filter').value;
  const acts = [...new Set(TI.filter(r =>
    (!fSub   || r.Subsystem === fSub) &&
    (!fPhase || r.Phase     === fPhase) &&
    (!fLoc   || r.Location  === fLoc)
  ).map(r => r.Activity).filter(Boolean))].sort();
  populateSelect('li-activity-filter', 'All activities', acts);
  if (!acts.includes(curAct)) document.getElementById('li-activity-filter').value = '';
}

function clearLIFilters() {
  _liKpiFilter = '';
  ['li-search','li-phase-filter','li-location-filter','li-activity-filter','li-status-filter'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  const isAdmin    = currentRoleUser?.role === 'admin';
  const userSubsys = currentRoleUser?.subsystem || null;
  if (isAdmin) {
    const el = document.getElementById('li-subsys-filter');
    if (el) el.value = '';
  }
  // Repopulate all dropdowns from full TI dataset so cascaded options are restored
  const fSub = isAdmin ? '' : (userSubsys || '');
  const subsystems = [...new Set(TI.map(r => r.Subsystem).filter(Boolean))].sort();
  const phases     = [...new Set(TI.filter(r => !fSub || r.Subsystem === fSub).map(r => String(r.Phase || '')).filter(Boolean))].sort((a,b) => a.localeCompare(b, undefined, {numeric:true}));
  const locs       = [...new Set(TI.filter(r => !fSub || r.Subsystem === fSub).map(r => r.Location).filter(Boolean))].sort();
  const acts       = [...new Set(TI.filter(r => !fSub || r.Subsystem === fSub).map(r => r.Activity).filter(Boolean))].sort();
  if (isAdmin) populateSelect('li-subsys-filter', 'All subsystems', subsystems);
  populateSelect('li-phase-filter',    'All phases',     phases);
  populateSelect('li-location-filter', 'All locations',  locs);
  populateSelect('li-activity-filter', 'All activities', acts);
  renderLITable();
}

function _liSortBy(col) {
  if (liSort.col === col) liSort.asc = !liSort.asc;
  else { liSort.col = col; liSort.asc = true; }
  renderLITable();
}

function renderLITable() {
  const search  = document.getElementById('li-search').value.toLowerCase();
  const subsysF = document.getElementById('li-subsys-filter').value;
  const phaseF  = document.getElementById('li-phase-filter').value;
  const locF    = document.getElementById('li-location-filter').value;
  const actF    = document.getElementById('li-activity-filter').value;
  const statusF = document.getElementById('li-status-filter').value;

  // Base data matching all user-selected filters (but NOT the KPI card filter)
  const baseData = TI.filter(r =>
    _isLatestAttempt(r) &&
    (!search  || (r.TestName     && r.TestName.toLowerCase().includes(search))
              || (r.TestCaseCode && r.TestCaseCode.toLowerCase().includes(search))
              || (r.Activity     && r.Activity.toLowerCase().includes(search))) &&
    (!subsysF || r.Subsystem === subsysF) &&
    (!phaseF  || r.Phase === phaseF) &&
    (!locF    || r.Location === locF) &&
    (!actF    || r.Activity === actF) &&
    (!statusF || r.Status === statusF)
  );

  // Update KPI mini cards from baseData (unaffected by KPI card click)
  const kpiCounts = {
    pass:       baseData.filter(r => ['Pass','Passed','Complete','Not Applicable'].includes(r.Status)).length,
    inprog:     baseData.filter(r => r.Status === 'In Progress').length,
    blocked:    baseData.filter(r => ['Fail','Failed','Blocked'].includes(r.Status)).length,
    notstarted: baseData.filter(r => !r.Status || r.Status === 'Not Started').length,
  };
  document.getElementById('li-passed').textContent = kpiCounts.pass.toLocaleString();
  document.getElementById('li-inprog').textContent = kpiCounts.inprog.toLocaleString();
  document.getElementById('li-failed').textContent = kpiCounts.blocked.toLocaleString();
  document.getElementById('li-open').textContent   = kpiCounts.notstarted.toLocaleString();

  // Highlight active KPI card
  const kpiMap = { pass: 'li-kpi-pass', inprog: 'li-kpi-inprog', blocked: 'li-kpi-blocked', notstarted: 'li-kpi-notstarted' };
  Object.entries(kpiMap).forEach(([key, id]) => {
    document.getElementById(id)?.classList.toggle('kpi-active', _liKpiFilter === key);
  });

  // Apply KPI card filter to table data
  let data = _liKpiFilter ? baseData.filter(r => _liMatchKpiStatus(r)) : baseData;

  if (liSort.col) {
    data = [...data].sort((a, b) => {
      const av = a[liSort.col] ?? '';
      const bv = b[liSort.col] ?? '';
      const cmp = String(av).localeCompare(String(bv), undefined, { numeric: true });
      return liSort.asc ? cmp : -cmp;
    });
  }

  const renderRows = data.slice(0, 500);
  const truncated  = data.length > 500 ? ` (showing first 500 — refine filters for more)` : '';

  // Dynamic column headers + body via generic column config
  const liVisCols = _colGetVisible('li');
  const liDefs = _colRegistry['li']?.defs || [];
  document.getElementById('li-thead').innerHTML = `<tr>${liVisCols.map(c => {
    const def = liDefs.find(d => d.id === c.id);
    const sk = def?.sortKey || '';
    return sk ? `<th data-sort="${sk}" onclick="_liSortBy('${sk}')">${def.label}</th>` : `<th>${def?.label || c.id}</th>`;
  }).join('')}<th style="width:48px;text-align:right;padding-right:8px;">
    <button aria-label="Configure columns" onclick="_colOpenEditor('li',renderLITable)" title="Configure columns"
      style="font-size:11px;padding:3px 8px;border:1px solid var(--gray-300);border-radius:5px;background:var(--gray-50);color:var(--gray-600);cursor:pointer;font-weight:600;white-space:nowrap;">${icon('settings')}</button>
  </th></tr>`;

  document.getElementById('li-body').innerHTML = renderRows.map(r => `
    <tr>${_colCells('li', r)}<td></td></tr>
  `).join('');

  document.getElementById('li-count').textContent =
    `Showing ${renderRows.length.toLocaleString()} of ${data.length.toLocaleString()} test cases${truncated}`;

  document.querySelectorAll('#li-table th').forEach(th => th.classList.remove('sorted','sorted-asc'));
  if (liSort.col) {
    const th = document.querySelector(`#li-table th[data-sort="${liSort.col}"]`);
    if (th) th.classList.add('sorted', liSort.asc ? 'sorted-asc' : '');
  }
}

// ==========================================
// PUNCH LIST PAGE
// ==========================================
let plSort = { col: null, asc: false };

function initPunchList() {
  document.getElementById('pl-summary').textContent = `${PL.length.toLocaleString()} punch items across all trades and locations`;

  const statuses = [...new Set(PL.map(r => r.Status).filter(Boolean))].sort();
  const priorities = ['high', 'medium', 'low'];
  const trades = [...new Set(PL.map(r => r.Trade && r.Trade.trim()).filter(Boolean))].sort();
  const types = [...new Set(PL.map(r => r.Type && r.Type.trim()).filter(Boolean))].sort();
  const locs = [...new Set(PL.map(r => r.Location).filter(Boolean))].sort();

  populateSelect('pl-status-filter', 'All statuses', statuses);
  populateSelect('pl-priority-filter', 'All priorities', priorities);
  populateSelect('pl-trade-filter', 'All trades', trades);
  populateSelect('pl-type-filter', 'All types', types);
  populateSelect('pl-location-filter', 'All locations', locs);

  ['pl-search','pl-status-filter','pl-priority-filter','pl-trade-filter','pl-type-filter','pl-location-filter'].forEach(id => {
    document.getElementById(id).addEventListener('input', renderPLTable);
  });

  document.querySelectorAll('#pl-table th[data-sort]').forEach(th => {
    th.addEventListener('click', () => {
      const col = th.dataset.sort;
      if (plSort.col === col) plSort.asc = !plSort.asc;
      else { plSort.col = col; plSort.asc = true; }
      renderPLTable();
    });
  });

  renderPLTable();
}

function clearPLFilters() {
  ['pl-search','pl-status-filter','pl-priority-filter','pl-trade-filter','pl-type-filter','pl-location-filter'].forEach(id => document.getElementById(id).value = '');
  renderPLTable();
}

function renderPLTable() {
  const search = document.getElementById('pl-search').value.toLowerCase();
  const statusF = document.getElementById('pl-status-filter').value;
  const priorityF = document.getElementById('pl-priority-filter').value;
  const tradeF = document.getElementById('pl-trade-filter').value;
  const typeF = document.getElementById('pl-type-filter').value;
  const locF = document.getElementById('pl-location-filter').value;

  let data = PL.filter(r =>
    (!search ||
      (r.Title && r.Title.toLowerCase().includes(search)) ||
      (r.Description && r.Description.toLowerCase().includes(search)) ||
      String(r.Number || '').includes(search)) &&
    (!statusF || r.Status === statusF) &&
    (!priorityF || r.Priority === priorityF) &&
    (!tradeF || (r.Trade && r.Trade.trim() === tradeF)) &&
    (!typeF || (r.Type && r.Type.trim() === typeF)) &&
    (!locF || r.Location === locF)
  );

  if (plSort.col) {
    data = [...data].sort((a, b) => {
      const av = a[plSort.col] || '';
      const bv = b[plSort.col] || '';
      const cmp = av.toString().localeCompare(bv.toString(), undefined, { numeric: true });
      return plSort.asc ? cmp : -cmp;
    });
  }

  const renderRows = data.slice(0, 500);

  const tbody = document.getElementById('pl-body');
  tbody.innerHTML = renderRows.map(r => `
    <tr>
      <td class="cell-mono">#${escapeHtml(String(r.Number || '—'))}</td>
      <td>
        <span class="cell-name">${escapeHtml(r.Title || '—')}</span>
        ${r.Overdue === 'Yes' ? '<span class="cell-sub" style="color:var(--bad);font-weight:600">' + icon('alert') + ' overdue</span>' : ''}
      </td>
      <td><span class="tag">${escapeHtml(r.Trade ? r.Trade.trim() : '—')}</span></td>
      <td>${getPriorityPill(r.Priority)}</td>
      <td>${escapeHtml(r.Type ? r.Type.trim() : '—')}</td>
      <td>${escapeHtml(r.Location || '—')}</td>
      <td>${getStatusBadge(r.Status)}</td>
    </tr>
  `).join('');

  // Update KPI cards with filtered counts
  document.getElementById('pl-high').textContent   = data.filter(r => r.Priority === 'high').length.toLocaleString();
  document.getElementById('pl-work').textContent   = data.filter(r => r.Status === 'Work Required').length.toLocaleString();
  document.getElementById('pl-ready').textContent  = data.filter(r => r.Status === 'Ready To Close').length.toLocaleString();
  document.getElementById('pl-closed').textContent = data.filter(r => r.Status === 'Closed').length.toLocaleString();

  const truncated = data.length > 500 ? ` (showing first 500 — refine filters for more)` : '';
  document.getElementById('pl-count').textContent = `Showing ${renderRows.length.toLocaleString()} of ${data.length.toLocaleString()} punch items${truncated}`;

  document.querySelectorAll('#pl-table th').forEach(th => th.classList.remove('sorted','sorted-asc'));
  if (plSort.col) {
    const th = document.querySelector(`#pl-table th[data-sort="${plSort.col}"]`);
    if (th) th.classList.add('sorted', plSort.asc ? 'sorted-asc' : '');
  }
}

// ==========================================
// LOCATIONS PAGE
// ==========================================
function initLocations() {
  const ti = _latestTI();

  // Get phases sorted ascending
  const phases = [...new Set(ti.map(r => String(r.Phase || '')).filter(Boolean))]
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

  // Build weight lookups ONCE per render — _wgtStat is called per phase + per
  // location which would otherwise rebuild these maps ~120× per page load.
  const _aw  = _buildActivityWeightLookup();
  const _tcw = _buildTestCaseWeightLookup();

  const grid = document.getElementById('locations-grid');

  // Flatten every phase/location into one list so cards pack into a single
  // dense grid (no wasted rows when a phase has only one location). Each card
  // carries its phase as a chip; a summary strip keeps the per-phase rollup.
  const cards = [];
  const phaseSummary = [];
  phases.forEach(phase => {
    const phaseTI = ti.filter(r => r.Phase === phase);
    const locs    = [...new Set(phaseTI.map(r => r.Location).filter(Boolean))].sort();
    if (!locs.length) return;

    const phaseWs  = _wgtStat(phaseTI, _aw, _tcw);
    const phasePct = phaseWs.totalW > 0 ? Math.round((phaseWs.completeW / phaseWs.totalW) * 100) : 0;
    phaseSummary.push({ phase, pct: phasePct, n: locs.length });

    locs.forEach(loc => {
      const locTI  = phaseTI.filter(r => r.Location === loc);
      const ws     = _wgtStat(locTI, _aw, _tcw);
      const pct    = ws.totalW > 0 ? Math.round((ws.completeW / ws.totalW) * 100) : 0;
      const passed = locTI.filter(r => ['Pass','Passed','Complete','Not Applicable'].includes(r.Status)).length;
      const total  = locTI.length;
      const punchOpen = (PUNCH_DB || []).filter(p =>
        p.location === loc && !p.is_deleted && !['Closed','Ready To Close'].includes(p.status)
      ).length;
      cards.push({ phase, loc, code: getLocationCode(loc), pct, passed, total, punchOpen });
    });
  });

  if (!cards.length) {
    grid.innerHTML = '<div class="docs-empty"><p>No test data available.</p></div>';
    return;
  }

  const summaryHTML = phaseSummary.length > 1 ? `
    <div class="loc-phase-summary">
      <button class="loc-phase-chip${_locPhaseFilter ? '' : ' active'}" data-phase="" onclick="_locFilterPhase('', this)">
        <span class="loc-phase-chip-name">All</span>
        <span class="loc-phase-chip-meta">${cards.length} location${cards.length !== 1 ? 's' : ''}</span>
      </button>
      ${phaseSummary.map(s => `
        <button class="loc-phase-chip${_locPhaseFilter === s.phase ? ' active' : ''}" data-phase="${escapeHtml(s.phase)}" onclick="_locFilterPhase('${escapeHtml(s.phase)}', this)">
          <span class="loc-phase-chip-name">${escapeHtml(s.phase)}</span>
          <span class="loc-phase-chip-meta">${s.pct}% · ${s.n} loc${s.n !== 1 ? 's' : ''}</span>
        </button>`).join('')}
    </div>` : '';

  const cardsHTML = `<div class="locations-cardgrid">${cards.map(c => {
    const hidden = _locPhaseFilter && c.phase !== _locPhaseFilter ? ' style="display:none"' : '';
    return `
      <div class="location-card" data-phase="${escapeHtml(c.phase)}"${hidden}>
        <div class="location-card-top">
          <span class="location-code">${escapeHtml(c.code)}</span>
          <span class="loc-card-phase">${escapeHtml(c.phase)}</span>
        </div>
        <div class="location-name">${escapeHtml(c.loc)}</div>
        <div class="location-progress">
          <div class="location-progress-meta"><span>Weighted progress</span><span><b>${c.pct}%</b></span></div>
          <div class="location-progress-bar"><div class="location-progress-fill" style="width:${c.pct}%"></div></div>
        </div>
        <div class="location-stats">
          <div class="location-stat"><div class="location-stat-value">${c.total.toLocaleString()}</div><div class="location-stat-label">Test Cases</div></div>
          <div class="location-stat"><div class="location-stat-value good">${c.passed.toLocaleString()}</div><div class="location-stat-label">Passed</div></div>
          <div class="location-stat"><div class="location-stat-value ${c.punchOpen > 0 ? 'bad' : ''}">${c.punchOpen}</div><div class="location-stat-label">Open Punch</div></div>
        </div>
      </div>`;
  }).join('')}</div>`;

  grid.innerHTML = summaryHTML + cardsHTML;
}

let _locPhaseFilter = '';
function _locFilterPhase(phase) {
  _locPhaseFilter = (_locPhaseFilter === phase) ? '' : phase;
  document.querySelectorAll('.loc-phase-chip').forEach(c =>
    c.classList.toggle('active', (c.getAttribute('data-phase') || '') === _locPhaseFilter));
  document.querySelectorAll('.locations-cardgrid .location-card').forEach(card => {
    card.style.display = (!_locPhaseFilter || card.getAttribute('data-phase') === _locPhaseFilter) ? '' : 'none';
  });
}

