let _trpExpanded = new Set();
let _trpSyncInFlight = false;
let _trpAutoSyncAttempted = new Set();
let _trpSearchTimer = null;

const ROLE_LABELS = {
  admin: 'Admin',
  field: 'Field',
  punch_manager: 'Punch Mgr',
  technician: 'Tech',
  client: 'Client',
};
const ROLE_TITLES = {
  admin: 'Administrator',
  field: 'Field Engineer',
  punch_manager: 'Punch List Manager',
  technician: 'Technician',
  client: 'Client / Inspector',
};

let currentRoleUser = null;
let currentProfile  = null;

// ==========================================================================
// SUPABASE AUTH — email + password, session persisted by Supabase
// ==========================================================================
function initAuth() {
  // Detect a Supabase password-recovery redirect *before* any session-restore
  // logic runs. Supabase email links return as `…/#access_token=…&type=recovery&…`
  // (or, for the newer PKCE flow, `?code=…&type=recovery`). If we don't spot
  // this up-front, our synchronous localStorage session restore wins the race
  // and `onLoggedIn()` fires before `PASSWORD_RECOVERY` arrives — so the user
  // ends up inside the app instead of the reset-password card.
  const _hash   = window.location.hash   || '';
  const _search = window.location.search || '';
  // Recovery is detected via any of:
  //  • our own `?reset=1` sentinel (set by submitPasswordReset's redirectTo)
  //  • the implicit-flow `type=recovery` marker in the URL hash
  //  • a PKCE `?code=…` query param when no normal session exists yet
  //    (PKCE recovery URLs carry no `type=recovery` marker; the sentinel above
  //    covers our own flow, and this catches links that bypassed it)
  const _hasResetSentinel  = /[?&]reset=1(?:&|$)/.test(_search);
  const _hasRecoveryMarker = /[#&?]type=recovery(?:&|$)/.test(_hash) ||
                             /[?&]type=recovery(?:&|$)/.test(_search);
  const _hasPkceCode       = /[?&]code=[^&]+/.test(_search);
  const _storedSessionPeek = _getSessionFromStorage();
  const _isRecoveryUrl = _hasResetSentinel
                      || _hasRecoveryMarker
                      || (_hasPkceCode && !_storedSessionPeek?.access_token);

  // onAuthStateChange handles SIGN_IN and SIGNED_OUT events.
  // We skip INITIAL_SESSION here — it's handled manually below via localStorage
  // because supabase-js GoTrueClient can hang during its internal init, which
  // would prevent INITIAL_SESSION from ever firing.
  _sb.auth.onAuthStateChange(async (event, session) => {
    console.log('[auth] event:', event);
    if (event === 'INITIAL_SESSION') return; // handled manually below
    if (event === 'TOKEN_REFRESHED') {
      console.log('[auth] token refreshed silently — no profile reload needed');
      return;
    }
    // User arrived via a "Reset Password" email link — show the reset form.
    // This takes priority over any stored session restore.
    if (event === 'PASSWORD_RECOVERY') {
      console.log('[auth] PASSWORD_RECOVERY — showing reset form');
      currentRoleUser = null;
      currentProfile  = null;
      document.getElementById('login-overlay')?.classList.remove('hidden');
      _showChangePasswordPanel(null); // null = recovery mode (not first-login)
      return;
    }
    if (event === 'SIGNED_IN' && session?.user) {
      // If we're in the middle of a recovery redirect, supabase-js fires
      // SIGNED_IN for the recovery session right alongside (or just before)
      // PASSWORD_RECOVERY. We must NOT load the profile here, otherwise the
      // overlay gets hidden and the reset card is never seen.
      if (_isRecoveryUrl) {
        console.log('[auth] SIGNED_IN suppressed — recovery URL in flight');
        return;
      }
      if (currentRoleUser) {
        // Already authenticated — this is the supabase-js GoTrueClient finishing its
        // delayed internal init. Ignore: we already restored from localStorage and
        // the user is on their current page. Re-running would navigate them away.
        console.log('[auth] SIGNED_IN — already authenticated, ignoring delayed event');
        return;
      }
      await _loadCurrentProfile(session.user, session.access_token);
    } else if (event === 'SIGNED_OUT' || !session) {
      _onSignedOut();
    }
  });

  // Recovery flow: skip the localStorage restore entirely and show the reset
  // card immediately. supabase-js will parse the URL hash, authenticate the
  // recovery session, and emit PASSWORD_RECOVERY (which re-asserts the card,
  // idempotent). We also strip the recovery params from the URL so a refresh
  // doesn't re-trigger the flow.
  if (_isRecoveryUrl) {
    console.log('[auth] recovery URL detected — showing reset card');
    document.getElementById('login-overlay')?.classList.remove('hidden');
    _showChangePasswordPanel(null);
    try {
      const cleanUrl = window.location.origin + window.location.pathname;
      window.history.replaceState({}, document.title, cleanUrl);
    } catch { /* noop */ }
    return;
  }

  // Restore existing session directly from localStorage — no supabase-js call needed.
  // This covers hard refresh and returning users without waiting for GoTrueClient init.
  const stored = _getSessionFromStorage();
  if (stored?.user && stored?.access_token) {
    console.log('[auth] restoring session from localStorage for:', stored.user.email);
    _loadCurrentProfile(stored.user, stored.access_token);
  } else {
    _onSignedOut();
  }
}

async function _loadCurrentProfile(user, accessToken) {
  // Reset sign-in button if it's stuck (in case we're called from onAuthStateChange
  // after a previous sign-in attempt that timed out mid-way).
  const btn = document.getElementById('auth-btn');
  if (btn) { btn.textContent = 'Signing in…'; btn.disabled = true; }

  try {
    // Use the access token passed in directly from onAuthStateChange — avoids calling
    // _sb.auth.getSession() which can hang while supabase-js is still settling.
    // Falls back to _getAuthHeader() for cases like session restore on page load.
    const authHeader = accessToken ? `Bearer ${accessToken}` : _getAuthHeader();
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 15000);
    const res = await fetch(
      `${SUPABASE_URL}/rest/v1/profiles?id=eq.${encodeURIComponent(user.id)}&select=*`,
      { signal: ctrl.signal, headers: { apikey: SUPABASE_ANON_KEY, Authorization: authHeader, Accept: 'application/json' } }
    );
    clearTimeout(timer);
    if (!res.ok) throw new Error(`profiles fetch failed (${res.status}): ${await res.text()}`);
    const rows = await res.json();
    console.log(`[_loadCurrentProfile] ✓ got ${rows.length} profile row(s)`);
    const data = rows?.[0];

    if (!data) {
      await _sb.auth.signOut();
      showAuthError('Your account is not set up yet — contact your admin.');
      if (btn) { btn.textContent = 'Sign In'; btn.disabled = false; }
      return;
    }
    if (!data.is_active) {
      await _sb.auth.signOut();
      showAuthError('Your account has been deactivated — contact your admin.');
      if (btn) { btn.textContent = 'Sign In'; btn.disabled = false; }
      return;
    }

    // First-login: admin set a temp password — user must create their own before entering
    if (data.must_change_password) {
      _showChangePasswordPanel(data);
      return;
    }

    currentProfile  = data;
    currentRoleUser = {
      name:      data.full_name,
      role:      data.role,
      title:     { admin:'Administrator', field_engineer:'Field Engineer', readonly:'Read Only', client:'Client' }[data.role] || data.role,
      subsystem: data.subsystem || null,
    };
    // Apply subsystem filter to test items if set
    if (currentRoleUser.subsystem) {
      TI = TI.filter(t => (t.Subsystem || '').toLowerCase() === currentRoleUser.subsystem.toLowerCase());
    }
    document.getElementById('login-overlay').classList.add('hidden');
    onLoggedIn();
  } catch(err) {
    console.error('Profile load failed:', err);
    showAuthError('Failed to load profile — try refreshing.');
    if (btn) { btn.textContent = 'Sign In'; btn.disabled = false; }
  }
}

function _onSignedOut() {
  currentRoleUser = null;
  currentProfile  = null;
  // Always reset the auth button so it never stays stuck on "Signing in…"
  const authBtn = document.getElementById('auth-btn');
  if (authBtn) { authBtn.textContent = 'Sign In'; authBtn.disabled = false; }
  document.getElementById('auth-error')?.textContent && (document.getElementById('auth-error').textContent = '');
  document.getElementById('login-overlay').classList.remove('hidden');
  _checkDbStatus(); // refresh connectivity indicator each time sign-in page appears
  document.querySelectorAll('.nav-role').forEach(l => l.style.display = 'none');
  // Reset admin mode
  _adminModeOn = false;
  const adminItems = document.getElementById('nav-admin-items');
  if (adminItems) adminItems.style.display = 'none';
  const regularItems = document.getElementById('nav-regular-items');
  if (regularItems) regularItems.style.display = '';
  document.getElementById('nav-admin-toggle')?.classList.remove('active');
  const pill = document.getElementById('nav-user-pill');
  if (pill) { pill.style.display = 'none'; pill.innerHTML = ''; }
  // Permission-model nav gating (P4-1a): hides modules the user lacks view on.
  if (typeof loadMyPermissions === 'function') loadMyPermissions(currentProfile);
  const navLogin = document.getElementById('nav-login');
  if (navLogin) navLogin.style.display = '';
}

async function signIn() {
  const email    = document.getElementById('auth-email').value.trim();
  const password = document.getElementById('auth-password').value;
  const btn      = document.getElementById('auth-btn');
  showAuthError('');
  if (!email || !password) { showAuthError('Enter your email and password.'); return; }
  btn.textContent = 'Signing in…'; btn.disabled = true;
  const { error } = await _sb.auth.signInWithPassword({ email, password });
  if (error) {
    showAuthError(error.message);
    btn.textContent = 'Sign In'; btn.disabled = false;
  }
  // onAuthStateChange handles the rest on success
}

async function signOut() {
  await _sb.auth.signOut();
  _sessionLog     = [];
  intakeAdditions = [];
  intakeStep      = 1;
  _resetIntakeRehydration();
  showPage('dashboard');
}

// ── Forgot Password modal ─────────────────────────────────────────────────
function openForgotPassword() {
  // Pre-fill with whatever is already typed in the sign-in email field
  const prefill = document.getElementById('auth-email')?.value.trim() || '';
  const inp = document.getElementById('fp-email');
  if (inp && prefill) inp.value = prefill;
  const msg = document.getElementById('fp-msg');
  if (msg) { msg.textContent = ''; msg.style.color = ''; }
  const btn = document.getElementById('fp-btn');
  if (btn) { btn.textContent = 'Send Reset Link'; btn.disabled = false; }
  const m = document.getElementById('forgot-password-modal');
  if (m) { m.style.display = 'flex'; }
  setTimeout(() => { if (!prefill) document.getElementById('fp-email')?.focus(); }, 50);
}

function closeForgotPassword() {
  const m = document.getElementById('forgot-password-modal');
  if (m) m.style.display = 'none';
}

async function submitPasswordReset() {
  const email = document.getElementById('fp-email')?.value.trim();
  const msg   = document.getElementById('fp-msg');
  const btn   = document.getElementById('fp-btn');
  if (!email) {
    if (msg) { msg.textContent = 'Please enter your email address.'; msg.style.color = '#dc2626'; }
    return;
  }
  if (btn) { btn.textContent = 'Sending…'; btn.disabled = true; }
  if (msg) { msg.textContent = ''; }
  // Use a clean origin+pathname URL with our own `?reset=1` sentinel so the
  // initAuth recovery-URL detection works regardless of whether Supabase uses
  // implicit (`#type=recovery`) or PKCE (`?code=…`) flow. Avoid sending
  // `window.location.href` since it may include unrelated hash/query state
  // that can collide with the auth params Supabase appends.
  const _redirectTo = `${window.location.origin}${window.location.pathname}?reset=1`;
  const { error } = await _sb.auth.resetPasswordForEmail(email, { redirectTo: _redirectTo });
  if (error) {
    if (msg) { msg.textContent = error.message; msg.style.color = '#dc2626'; }
    if (btn) { btn.textContent = 'Send Reset Link'; btn.disabled = false; }
  } else {
    if (msg) { msg.textContent = '✓ Reset link sent — check your inbox.'; msg.style.color = '#16a34a'; }
    if (btn) { btn.textContent = 'Link Sent'; btn.disabled = true; }
    setTimeout(closeForgotPassword, 3000);
  }
}

function showAuthError(msg) {
  const el = document.getElementById('auth-error');
  if (el) el.textContent = msg;
}

// ── First-login change-password flow ─────────────────────────────────────
let _pendingProfile = null; // holds profile row while awaiting password change

function _showChangePasswordPanel(profileData) {
  // profileData = profile row  →  first-login mode (must_change_password)
  // profileData = null          →  password recovery mode (reset link from email)
  _pendingProfile = profileData;

  const isRecovery = profileData === null;
  const loginCard  = document.querySelector('#login-overlay .login-card:not(#cp-card)');
  const cpCard     = document.getElementById('cp-card');

  // Swap cards — keep cinematic background visible
  if (loginCard) loginCard.style.display = 'none';
  if (cpCard)    cpCard.style.display    = '';

  // Update copy to match the mode
  const titleEl = document.getElementById('cp-title');
  const subEl   = document.getElementById('cp-sub');
  const btnEl   = document.getElementById('cp-btn');
  if (isRecovery) {
    if (titleEl) titleEl.textContent = 'Reset Your Password';
    if (subEl)   subEl.innerHTML    = 'Enter and confirm your new password below.';
    if (btnEl)   btnEl.textContent  = 'Save New Password';
  } else {
    if (titleEl) titleEl.textContent = 'Set Your Password';
    if (subEl)   subEl.innerHTML    = 'Your account was created with a temporary password.<br>Choose a new password to continue.';
    if (btnEl)   btnEl.textContent  = 'Set Password & Continue';
  }

  // Reset any previous error/state
  const errEl = document.getElementById('cp-error');
  if (errEl) errEl.textContent = '';
  if (btnEl) btnEl.disabled = false;
  const authBtn = document.getElementById('auth-btn');
  if (authBtn) { authBtn.textContent = 'Sign In'; authBtn.disabled = false; }

  setTimeout(() => document.getElementById('cp-new-password')?.focus(), 80);
}

function _resetCpCard() {
  // Clear inputs and restore card to initial hidden state
  const cpCard    = document.getElementById('cp-card');
  const loginCard = document.querySelector('#login-overlay .login-card:not(#cp-card)');
  if (cpCard)    cpCard.style.display    = 'none';
  if (loginCard) loginCard.style.display = '';
  const pw1 = document.getElementById('cp-new-password');
  const pw2 = document.getElementById('cp-confirm-password');
  const err = document.getElementById('cp-error');
  const btn = document.getElementById('cp-btn');
  if (pw1) pw1.value = '';
  if (pw2) pw2.value = '';
  if (err) err.textContent = '';
  if (btn) { btn.textContent = 'Set Password & Continue'; btn.disabled = false; }
}

async function submitChangePassword() {
  const pw1 = document.getElementById('cp-new-password')?.value  || '';
  const pw2 = document.getElementById('cp-confirm-password')?.value || '';
  const err = document.getElementById('cp-error');
  const btn = document.getElementById('cp-btn');
  if (err) err.textContent = '';

  if (!pw1)           { if (err) err.textContent = 'Enter a new password.'; return; }
  if (pw1.length < 8) { if (err) err.textContent = 'Password must be at least 8 characters.'; return; }
  if (pw1 !== pw2)    { if (err) err.textContent = 'Passwords do not match.'; return; }

  if (btn) { btn.textContent = 'Saving…'; btn.disabled = true; }

  const { error: updErr } = await _sb.auth.updateUser({ password: pw1 });
  if (updErr) {
    if (err) err.textContent = updErr.message;
    if (btn) { btn.textContent = _pendingProfile ? 'Set Password & Continue' : 'Save New Password'; btn.disabled = false; }
    return;
  }

  // ── Branch A: first-login (temp password set by admin) ───────────────────
  if (_pendingProfile) {
    await _sb.from('profiles').update({ must_change_password: false }).eq('id', _pendingProfile.id);
    const data = { ..._pendingProfile, must_change_password: false };
    _pendingProfile = null;

    currentProfile  = data;
    currentRoleUser = {
      name:      data.full_name,
      role:      data.role,
      title:     { admin:'Administrator', field_engineer:'Field Engineer', readonly:'Read Only', client:'Client' }[data.role] || data.role,
      subsystem: data.subsystem || null,
    };
    if (currentRoleUser.subsystem) {
      TI = TI.filter(t => (t.Subsystem || '').toLowerCase() === currentRoleUser.subsystem.toLowerCase());
    }
    _resetCpCard();
    document.getElementById('login-overlay').classList.add('hidden');
    toast('Password updated — welcome to the portal!', 'success');
    onLoggedIn();
    return;
  }

  // ── Branch B: password recovery (reset link from email) ──────────────────
  // The user is signed in via the recovery token. Fetch their profile directly
  // (bypassing _loadCurrentProfile's must_change_password intercept) and load the app.
  try {
    const { data: { session } } = await _sb.auth.getSession();
    if (!session?.user) throw new Error('No session after password update.');

    const ctrl  = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 12000);
    const res   = await fetch(
      `${SUPABASE_URL}/rest/v1/profiles?id=eq.${encodeURIComponent(session.user.id)}&select=*`,
      { signal: ctrl.signal, headers: { apikey: SUPABASE_ANON_KEY, Authorization: `Bearer ${session.access_token}`, Accept: 'application/json' } }
    );
    clearTimeout(timer);
    if (!res.ok) throw new Error(`Profile fetch failed (${res.status})`);
    const rows = await res.json();
    const data = rows?.[0];
    if (!data) throw new Error('Profile not found.');

    // If the account also had must_change_password set, clear it while we're here
    if (data.must_change_password) {
      await _sb.from('profiles').update({ must_change_password: false }).eq('id', data.id);
      data.must_change_password = false;
    }
    if (!data.is_active) throw new Error('Account is deactivated — contact your admin.');

    currentProfile  = data;
    currentRoleUser = {
      name:      data.full_name,
      role:      data.role,
      title:     { admin:'Administrator', field_engineer:'Field Engineer', readonly:'Read Only', client:'Client' }[data.role] || data.role,
      subsystem: data.subsystem || null,
    };
    if (currentRoleUser.subsystem) {
      TI = TI.filter(t => (t.Subsystem || '').toLowerCase() === currentRoleUser.subsystem.toLowerCase());
    }
    _resetCpCard();
    document.getElementById('login-overlay').classList.add('hidden');
    toast('Password reset — welcome back!', 'success');
    onLoggedIn();
  } catch (e) {
    console.error('[submitChangePassword] recovery profile load failed:', e);
    // Fallback: reset card and ask them to sign in with the new password
    _resetCpCard();
    document.getElementById('login-overlay')?.classList.remove('hidden');
    showAuthError('Password saved. Please sign in with your new password.');
  }
}

// ── DB connectivity indicator on sign-in page ─────────────────────────────
async function _checkDbStatus() {
  const dot   = document.getElementById('login-db-dot');
  const label = document.getElementById('login-db-label');
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), 6000);
    const res = await fetch(`${SUPABASE_URL}/rest/v1/profiles?select=id&limit=1`, {
      method: 'GET',
      signal: ctrl.signal,
      headers: { apikey: SUPABASE_ANON_KEY }
    });
    clearTimeout(timer);
    if (res.ok || res.status === 406) {
      // 406 = "not acceptable" (format mismatch) but server responded → online
      if (dot)   { dot.classList.add('online'); dot.classList.remove('offline'); }
      if (label) label.textContent = 'SYSTEM ONLINE';
    } else {
      if (dot)   { dot.classList.add('offline'); dot.classList.remove('online'); }
      if (label) label.textContent = 'SYSTEM DEGRADED';
    }
  } catch {
    if (dot)   { dot.classList.add('offline'); dot.classList.remove('online'); }
    if (label) label.textContent = 'SYSTEM OFFLINE';
  }
}

