// First nav page the signed-in user may actually view, preferring `preferred`.
// Used for the post-login landing page so it respects access levels: a module at
// NONE is hidden from the nav AND skipped as a landing target. Falls back to the
// first viewable regular nav link, then dashboard, then the preferred page.
function _navLandingPage(preferred) {
  const canView = (page) => {
    if (typeof uiCan !== 'function' || typeof PAGE_MODULE === 'undefined') return true;
    const m = PAGE_MODULE[page];
    return !m || uiCan(m, 'view');
  };
  if (canView(preferred)) return preferred;
  for (const l of document.querySelectorAll('#nav-regular-items .nav-link[data-page]')) {
    if (canView(l.dataset.page)) return l.dataset.page;
  }
  return canView('dashboard') ? 'dashboard' : preferred;
}

function onLoggedIn() {
  document.querySelectorAll('.nav-role').forEach(link => {
    const allowed = (link.dataset.role || '').split(' ');
    link.style.display = allowed.includes(currentRoleUser.role) ? '' : 'none';
  });
  // Filter individual items inside the Tools dropdown
  document.querySelectorAll('.nav-dd-role').forEach(item => {
    const allowed = (item.dataset.role || '').split(' ');
    item.style.display = allowed.includes(currentRoleUser.role) ? '' : 'none';
  });
  // Permission-model nav gating (AUTHORITATIVE): runs after the legacy role
  // filter so per-module permissions win — modules the user lacks 'view' on
  // (e.g. access level NONE) are removed from the nav entirely, and delegated
  // modules the role would have hidden are revealed. Async (loads template +
  // overrides, then calls _applyPermNav). Fail-open if it errors (RLS enforces).
  const _permsReady = (typeof loadMyPermissions === 'function')
    ? Promise.resolve(loadMyPermissions(currentProfile)) : Promise.resolve();
  const navLogin = document.getElementById('nav-login');
  if (navLogin) navLogin.style.display = 'none';

  // Populate sidebar user card
  const pill = document.getElementById('nav-user-pill');
  if (pill) {
    pill.style.display = 'flex';
    const initials = currentRoleUser.name.split(' ').filter(Boolean).slice(0,2).map(n=>n[0]).join('').toUpperCase();
    // Role is retired from the UI: admins show as Global Administrator; everyone
    // else shows their permission template (filled in async by loadMyPermissions).
    const roleLabel = currentRoleUser.role === 'admin' ? 'Global Administrator' : 'Member';
    const subNote = currentRoleUser.subsystem ? ` · ${currentRoleUser.subsystem}` : '';
    pill.innerHTML = `
      <div class="user-avatar" style="width:32px;height:32px;font-size:12px;flex-shrink:0;">${initials}</div>
      <div class="sidenav-user-info">
        <div class="sidenav-user-name">${escapeHtml(currentRoleUser.name)}</div>
        <div class="sidenav-user-role">${roleLabel}${subNote}</div>
      </div>
      <button class="sidenav-signout" onclick="signOut()" title="Sign out">
        <svg width="15" height="15" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M3 3a1 1 0 00-1 1v12a1 1 0 001 1h8a1 1 0 100-2H4V5h7a1 1 0 100-2H3zm10.293 4.293a1 1 0 011.414 0l3 3a1 1 0 010 1.414l-3 3a1 1 0 01-1.414-1.414L14.586 11H9a1 1 0 110-2h5.586l-1.293-1.293a1 1 0 010-1.414z" clip-rule="evenodd"/></svg>
      </button>
    `;
  }

  const homeByRole = { admin:'test-register', field_engineer:'field-intake', readonly:'dashboard', client:'dashboard' }[currentRoleUser.role] || 'dashboard';
  // Land on the role's home page only if the user may view it; otherwise the
  // first viewable nav page. Wait for permissions so NONE modules are skipped.
  _permsReady.then(() => showPage(_navLandingPage(homeByRole))).catch(() => showPage(homeByRole));

  // Re-load all data tables now that we have an authenticated token.
  // RLS blocks unauthenticated startup loads, so this is the real data fetch.
  Promise.all([
    loadTestItems(),
    loadTemplates(),
    loadLocations(),
    loadPunchDB(),
    loadFieldsetConfig(),
    _loadProfileUsers(),
    loadTestReports(),
    loadActivityRecords(),
    loadWeights(),
    loadP6Data(),
    loadAssetData(),
    loadRMAs(),
    loadTasks(),
    loadSoftwareConfigs(),
    loadSwEquipment(),
    loadSwDeployments(),
    loadVehicles(),
    loadPunchTemplates(),
    loadForms(),
    loadDrawingsData(),
    _colLoadAll(),
    (typeof loadTeamMembers==='function'?loadTeamMembers():Promise.resolve()),
  ]).then(() => {
    // Re-init views with freshly loaded data
    initLineItems();
    if (typeof initOrg==='function') initOrg();
    initActivities();
    renderAdminPortal(); renderAdminTemplates(); renderTestRegister(); renderFieldIntake();
    renderPunchWorkflow(); renderAuditLog(); renderTestReporting();
    refreshAuditLog().catch(err => console.warn('[audit] refresh failed:', err.message));
  }).catch(err => console.warn('[onLoggedIn data reload] partial failure:', err.message));
}

// ==========================================================================
// TOAST NOTIFICATIONS
// ==========================================================================
function toast(msg, type = 'success') {
  const el = document.createElement('div');
  el.className = 'toast ' + type;
  const statusIcon = type === 'success' ? icon('check-circle') : type === 'error' ? icon('ban') : type === 'warn' ? icon('alert') : icon('info');
  el.innerHTML = `<div class="icon">${statusIcon}</div><div>${escapeHtml(msg)}</div>`;
  document.body.appendChild(el);
  setTimeout(() => { el.style.opacity = '0'; el.style.transform = 'translateY(20px)'; el.style.transition = 'all 0.3s'; }, 3500);
  setTimeout(() => el.remove(), 4000);
}

function logAudit(action, target, details, notes = '') {
  if (!currentRoleUser) return;
  const entry = {
    id: 'a-' + Date.now(),
    user: currentRoleUser.name,
    role: currentRoleUser.role,
    action, target, details,
    timestamp: new Date().toISOString(),
    notes,
  };
  AUDIT_LOG.unshift(entry);
  _dbInsert('audit_log', [{
    id: entry.id,
    user_name: entry.user,
    role: entry.role,
    action: entry.action,
    target: entry.target,
    details: entry.details,
    timestamp: entry.timestamp,
    notes: entry.notes,
    table_name: 'audit_log',
    record_id: entry.id,
    source: 'Portal Audit',
  }]).catch(err => console.warn('[audit] persist skipped:', err.message));
  renderAuditLog();
}

function dateAgo(iso) {
  if (!iso) return '—';
  const d = new Date(iso);
  const now = new Date();
  const diff = (now - d) / 1000;
  if (diff < 60) return 'just now';
  if (diff < 3600) return Math.floor(diff/60) + 'm ago';
  if (diff < 86400) return Math.floor(diff/3600) + 'h ago';
  if (diff < 604800) return Math.floor(diff/86400) + 'd ago';
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

