// ==========================================================================
// ADMIN: WEIGHTS — manage shared activity weights (Subsystem + Activity).
// Each activity row has a "View Test Cases" button that opens a modal with
// the deduplicated test cases that live inside that activity, each with its
// own editable weight (shared on Code+Name across every instance).
// ==========================================================================
let _awSearch    = '';
let _awSubFilter = '';

function renderAdminWeights() {
  const root = document.getElementById('admin-weights-content');
  if (!root || !currentRoleUser) return;
  if (!uiCan('weights', 'view')) { root.innerHTML = cxEmpty({ icon: 'lock', title: 'Not authorized', message: 'You don\u2019t have access to this admin area.' }); return; }
  root.innerHTML = _adminWeightsHTML();
}

// Build the activity list with a per-activity count of distinct test cases
// (deduplicated by Code+TestName across all locations).
function _awGetActivityRows() {
  const actLookup = _buildActivityWeightLookup();
  const tcLookup  = _buildTestCaseWeightLookup();
  const seen = new Map(); // sub||act → row aggregator
  for (const r of TI) {
    if (r.IsParent) continue;
    const sub = r.Subsystem || '';
    const act = r.Activity  || '';
    if (!sub || !act) continue;
    const key = `${sub}||${act}`;
    if (!seen.has(key)) {
      seen.set(key, {
        subsystem:      sub,
        activity_name:  act,
        weight:         actLookup.get(key) ?? 1,
        instances:      0,
        tcKeys:         new Set(), // distinct test case identities
        weightedTcs:    0,         // count of distinct test cases with weight ≠ 1
      });
    }
    const row = seen.get(key);
    row.instances++;
    const tcKey = `${r.TestCaseCode || ''}||${r.TestName || ''}`;
    if (!row.tcKeys.has(tcKey)) {
      row.tcKeys.add(tcKey);
      if ((tcLookup.get(tcKey) ?? 1) !== 1) row.weightedTcs++;
    }
  }
  return [...seen.values()].map(r => ({
    ...r,
    distinctTcCount: r.tcKeys.size,
  }));
}

function _awSetSearch(v) {
  _awSearch = v;
  const body = document.getElementById('aw-table-body');
  if (body) body.innerHTML = _awActivityRowsHTML();
  const countEl = document.getElementById('aw-count');
  if (countEl) countEl.textContent = `${_awFilteredActivityRows().length}`;
}

function _awSetSubFilter(v) {
  _awSubFilter = v;
  renderAdminWeights();
}

function _awFilteredActivityRows() {
  const q = (_awSearch || '').toLowerCase().trim();
  return _awGetActivityRows()
    .filter(r => !_awSubFilter || r.subsystem === _awSubFilter)
    .filter(r => !q || r.activity_name.toLowerCase().includes(q) || r.subsystem.toLowerCase().includes(q))
    .sort((a, b) => a.subsystem.localeCompare(b.subsystem) || a.activity_name.localeCompare(b.activity_name));
}

function _adminWeightsHTML() {
  const subs = [...new Set(TI.map(r => r.Subsystem).filter(Boolean))].sort();
  const rows = _awFilteredActivityRows();

  return `
    <div class="admin-section">
      <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:14px;">
        <div>
          <div class="admin-section-title">Activity & Test Case Weights</div>
          <p class="section-sub">
            Set a shared weight on each activity (<b>Subsystem + Activity Name</b>).
            Open an activity to weight its test cases — the same Test Code + Name applies everywhere it lives.
          </p>
        </div>
      </div>

      <div class="filter-bar" style="margin-top:6px;">
        <input id="aw-search" class="filter-input" type="text"
          placeholder="Search activity or subsystem…"
          value="${escapeHtml(_awSearch)}" oninput="_awSetSearch(this.value)">
        <select class="filter-select" onchange="_awSetSubFilter(this.value)">
          <option value="">All subsystems</option>
          ${subs.map(s => `<option value="${escapeHtml(s)}" ${_awSubFilter === s ? 'selected' : ''}>${escapeHtml(s)}</option>`).join('')}
        </select>
        <span style="margin-left:auto;font-size:12px;color:var(--gray-500);">
          <span id="aw-count"><b>${rows.length}</b></span> activities
        </span>
      </div>

      <div class="data-card">
        <div class="table-wrap">
          <table class="data-table">
            <thead>
              <tr>
                <th style="width:200px;">Subsystem</th>
                <th>Activity Name</th>
                <th style="width:120px;text-align:right;">Test Cases</th>
                <th style="width:120px;text-align:right;">Instances</th>
                <th style="width:130px;">Activity Weight</th>
                <th style="width:180px;"></th>
              </tr>
            </thead>
            <tbody id="aw-table-body">
              ${_awActivityRowsHTML()}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  `;
}

function _awActivityRowsHTML() {
  const rows = _awFilteredActivityRows();
  if (!rows.length) {
    return `<tr><td colspan="6" style="padding:20px;text-align:center;color:var(--gray-500);">No activities match the current filter.</td></tr>`;
  }
  return rows.map(r => {
    const safeSub = escapeHtml(r.subsystem);
    const safeAct = escapeHtml(r.activity_name);
    const dataAttr = `data-sub="${safeSub}" data-act="${safeAct}"`;
    const wClass = r.weight !== 1 ? 'aw-weight-custom' : '';
    const tcBadge = r.weightedTcs
      ? `<span class="aw-weighted-pill" title="${r.weightedTcs} test case${r.weightedTcs!==1?'s':''} weighted ≠ 1">${icon('scale')}️ ${r.weightedTcs} weighted</span>`
      : '';
    return `
      <tr>
        <td><span class="tag">${safeSub}</span></td>
        <td><span style="font-weight:600;font-size:13px;">${safeAct}</span></td>
        <td style="text-align:right;font-size:12px;color:var(--gray-700);"><b>${r.distinctTcCount}</b></td>
        <td style="text-align:right;color:var(--gray-500);font-size:12px;">${r.instances}</td>
        <td>
          <input type="number" min="0.1" step="0.5" ${dataAttr}
            class="form-input aw-weight-input ${wClass}"
            style="width:100px;text-align:right;"
            value="${r.weight}"
            onchange="_awSaveActivityWeight(this)"
            title="Weight applied at every location for ${safeSub} · ${safeAct}">
        </td>
        <td>
          <button class="admin-action-btn tr-mini-btn" style="display:inline-flex;align-items:center;gap:6px;"
            onclick="_awOpenTestCasesModal('${safeSub}','${safeAct}')">
            ${r.distinctTcCount} cases ${tcBadge ? `· ${tcBadge}` : ''} →
          </button>
        </td>
      </tr>`;
  }).join('');
}

// ── Test Cases modal — one row per distinct (code, name) inside the activity ──
function _awGetTestCasesInActivity(sub, act) {
  const tcLookup = _buildTestCaseWeightLookup();
  const seen = new Map();
  for (const r of TI) {
    if (r.IsParent) continue;
    if ((r.Subsystem || '') !== sub || (r.Activity || '') !== act) continue;
    const code = r.TestCaseCode || '';
    const name = r.TestName     || '';
    if (!code && !name) continue;
    const key = `${code}||${name}`;
    if (!seen.has(key)) {
      seen.set(key, {
        test_case_code: code,
        test_name:      name,
        weight:         tcLookup.get(key) ?? 1,
        instances:      0,
        locations:      new Set(),
      });
    }
    const row = seen.get(key);
    row.instances++;
    if (r.Location) row.locations.add(r.Location);
  }
  return [...seen.values()]
    .map(r => ({ ...r, locations: [...r.locations].sort() }))
    .sort((a, b) =>
      a.test_case_code.localeCompare(b.test_case_code, undefined, { numeric: true })
      || a.test_name.localeCompare(b.test_name)
    );
}

function _awOpenTestCasesModal(sub, act) {
  const cases = _awGetTestCasesInActivity(sub, act);
  const bulkBar = `
    <div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--gray-50);border-bottom:1px solid var(--gray-200);">
      <span style="font-size:11px;font-weight:700;color:var(--gray-500);text-transform:uppercase;">Bulk apply:</span>
      <input type="number" id="aw-bulk-val" class="form-input" min="0" step="0.5" placeholder="weight"
        style="width:90px;font-size:12px;padding:5px 8px;text-align:right;">
      <button class="admin-action-btn tr-mini-btn" onclick="_awApplyBulkWeight()">Apply to all ${cases.length} test cases</button>
      <span style="margin-left:auto;font-size:11px;color:var(--gray-500);">All changes save instantly</span>
    </div>`;

  const rowsHTML = cases.length
    ? cases.map(c => {
        const safeCode = escapeHtml(c.test_case_code);
        const safeName = escapeHtml(c.test_name);
        const wClass = c.weight !== 1 ? 'aw-weight-custom' : '';
        return `
          <tr>
            <td><span class="cell-mono">${safeCode || '—'}</span></td>
            <td><span style="font-weight:600;font-size:13px;">${safeName || '—'}</span></td>
            <td style="text-align:right;color:var(--gray-500);font-size:12px;">${c.instances}</td>
            <td>
              <input type="number" min="0.1" step="0.5"
                data-code="${safeCode}" data-name="${safeName}"
                class="form-input aw-weight-input aw-tc-input ${wClass}"
                style="width:100px;text-align:right;"
                value="${c.weight}"
                onchange="_awSaveTestCaseWeight(this)"
                title="Weight for every instance of ${safeCode || '—'} · ${safeName || '—'}">
            </td>
          </tr>`;
      }).join('')
    : `<tr><td colspan="4" style="padding:24px;text-align:center;color:var(--gray-500);">No test cases under this activity.</td></tr>`;

  modal({
    title: `Test Cases in ${act}`,
    sub:   `${sub} · ${cases.length} distinct test case${cases.length !== 1 ? 's' : ''} (deduplicated across all locations)`,
    size:  'large',
    body: `
      <div class="data-card" style="margin-bottom:0;overflow:hidden;">
        ${bulkBar}
        <div class="table-wrap" style="max-height:60vh;overflow:auto;">
          <table class="data-table">
            <thead>
              <tr>
                <th style="width:160px;">Code</th>
                <th>Test Name</th>
                <th style="width:100px;text-align:right;">Instances</th>
                <th style="width:130px;">Weight</th>
              </tr>
            </thead>
            <tbody>${rowsHTML}</tbody>
          </table>
        </div>
      </div>`,
    footer: `<button class="form-secondary" onclick="closeModal()">Done</button>`,
  });
}

async function _awApplyBulkWeight() {
  if (typeof uiCan === 'function' && !uiCan('weights', 'bulk_apply')) { toast('You do not have permission to bulk-apply weights', 'error'); return; }
  const val = parseFloat(document.getElementById('aw-bulk-val')?.value);
  if (!isFinite(val) || val <= 0) { toast('Weight must be greater than 0', 'error'); return; }
  const inputs = [...document.querySelectorAll('.aw-tc-input')];
  if (!inputs.length) return;

  // Build the rows to upsert in ONE request — no N-fan-out
  const now = new Date().toISOString();
  const rows = inputs.map(el => ({
    test_case_code: el.getAttribute('data-code') || '',
    test_name:      el.getAttribute('data-name') || '',
    weight:         val,
    updated_at:     now,
  }));

  inputs.forEach(el => { el.value = val; el.disabled = true; });
  try {
    const saved = await _dbUpsert('test_case_weights', rows, 'test_case_code,test_name');
    // Merge results into the in-memory cache
    (saved || []).forEach(row => {
      const idx = _testCaseWeights.findIndex(r =>
        r.test_case_code === row.test_case_code && r.test_name === row.test_name
      );
      if (idx >= 0) _testCaseWeights[idx] = row;
      else _testCaseWeights.push(row);
    });
    inputs.forEach(el => el.classList.toggle('aw-weight-custom', val !== 1));
    toast(`Applied weight ${val} to ${rows.length} test case${rows.length !== 1 ? 's' : ''}`, 'success');
    const body = document.getElementById('aw-table-body');
    if (body) body.innerHTML = _awActivityRowsHTML();
    _tryRefreshDashboard?.();
  } catch (e) {
    toast(`Bulk apply failed: ${e.message}`, 'error');
  } finally {
    inputs.forEach(el => { el.disabled = false; });
  }
}

async function _awSaveActivityWeight(el) {
  if (typeof uiCan === 'function' && !uiCan('weights', 'edit_activity')) { toast('You do not have permission to edit weights', 'error'); return; }
  const sub = el.getAttribute('data-sub')  || '';
  const act = el.getAttribute('data-act')  || '';
  const w   = parseFloat(el.value);
  if (!isFinite(w) || w <= 0) { toast('Weight must be greater than 0', 'error'); return; }
  el.disabled = true;
  try {
    // Upsert into activity_weights, then refresh in-memory cache
    const [row] = await _dbUpsert('activity_weights',
      [{ subsystem: sub, activity_name: act, weight: w, updated_at: new Date().toISOString() }],
      'subsystem,activity_name');
    if (row) {
      const idx = _activityWeights.findIndex(r => r.subsystem === sub && r.activity_name === act);
      if (idx >= 0) _activityWeights[idx] = row;
      else _activityWeights.push(row);
    }
    el.classList.toggle('aw-weight-custom', w !== 1);
    toast(`Saved · ${sub} · ${act} → ${w}`, 'success');
    _tryRefreshDashboard?.();
  } catch (e) {
    toast(`Save failed: ${e.message}`, 'error');
  } finally {
    el.disabled = false;
  }
}

async function _awSaveTestCaseWeight(el) {
  if (typeof uiCan === 'function' && !uiCan('weights', 'edit_test_case')) { toast('You do not have permission to edit weights', 'error'); return; }
  const code = el.getAttribute('data-code') || '';
  const name = el.getAttribute('data-name') || '';
  const w    = parseFloat(el.value);
  if (!isFinite(w) || w <= 0) { toast('Weight must be greater than 0', 'error'); return; }
  el.disabled = true;
  try {
    const [row] = await _dbUpsert('test_case_weights',
      [{ test_case_code: code, test_name: name, weight: w, updated_at: new Date().toISOString() }],
      'test_case_code,test_name');
    if (row) {
      const idx = _testCaseWeights.findIndex(r => r.test_case_code === code && r.test_name === name);
      if (idx >= 0) _testCaseWeights[idx] = row;
      else _testCaseWeights.push(row);
    }
    el.classList.toggle('aw-weight-custom', w !== 1);
    toast(`Saved · ${code} → ${w}`, 'success');
    // Refresh the underlying activity table so its "X weighted" pill updates
    const body = document.getElementById('aw-table-body');
    if (body) body.innerHTML = _awActivityRowsHTML();
    _tryRefreshDashboard?.();
  } catch (e) {
    toast(`Save failed: ${e.message}`, 'error');
  } finally {
    el.disabled = false;
  }
}

function renderAdminTemplates() {
  const root = document.getElementById('admin-templates-content');
  if (!root || !currentRoleUser) return;
  if (!uiCan('templates', 'view')) { root.innerHTML = cxEmpty({ icon: 'lock', title: 'Not authorized', message: 'You don\u2019t have access to this admin area.' }); return; }
  root.innerHTML = _adminTemplatesHTML();
}

function renderAdminLocations() {
  const root = document.getElementById('admin-locations-content');
  if (!root || !currentRoleUser) return;
  if (!uiCan('locations', 'view')) { root.innerHTML = cxEmpty({ icon: 'lock', title: 'Not authorized', message: 'You don\u2019t have access to this admin area.' }); return; }
  root.innerHTML = _adminLocationsHTML();
}

function renderAdminFieldConfig() {
  const root = document.getElementById('admin-fieldconfig-content');
  if (!root || !currentRoleUser) return;
  if (!uiCan('forms', 'view')) { root.innerHTML = cxEmpty({ icon: 'lock', title: 'Not authorized', message: 'You don\u2019t have access to this admin area.' }); return; }
  root.innerHTML = _adminFieldConfigHTML();
}

// Directory now hosts the merged Permissions experience as a single tabbed
// surface: the user directory plus the permission-template and per-user-override
// tools that used to live on a standalone Permissions page. Tabs appear per the
// viewer's module access — `directory` gates Users, `admin` gates the two
// permission tabs — so a user sees only what they're allowed to manage.
let _dirTab = 'users';          // 'users' | 'templates' | 'overrides'
let _dirPermsLoaded = false;    // perms data (_paLoad) cached for this page visit

function renderAdminDirectory() {
  const root = document.getElementById('admin-directory-content');
  if (!root || !currentRoleUser) return;
  const canDir   = uiCan('directory', 'view');
  const canPerms = uiCan('admin', 'view');
  if (!canDir && !canPerms) {
    root.innerHTML = cxEmpty({ icon: 'lock', title: 'Not authorized', message: 'You don\u2019t have access to this admin area.' });
    return;
  }
  const tabs = [];
  if (canDir)   tabs.push({ id: 'users',     label: 'Users' });
  if (canPerms) tabs.push({ id: 'templates', label: 'Permission Templates' }, { id: 'overrides', label: 'Users & Overrides' });
  if (!tabs.some(t => t.id === _dirTab)) _dirTab = tabs[0].id;
  root.innerHTML = `
    <div class="admin-tabs">
      ${tabs.map(t => `<button class="admin-tab${_dirTab === t.id ? ' active' : ''}" onclick="setDirectoryTab('${t.id}')">${t.label}</button>`).join('')}
    </div>
    <div id="dir-tab-body"></div>
  `;
  renderDirectoryTabBody();
}

function setDirectoryTab(tab) {
  _dirTab = tab;
  renderAdminDirectory();
}

function renderDirectoryTabBody() {
  const body = document.getElementById('dir-tab-body');
  if (!body) return;
  if (_dirTab === 'users') {
    body.innerHTML = _adminDirectoryHTML();
    _loadDirectoryUsers();
    return;
  }
  // Permission Templates / Users & Overrides — backed by perms-admin.js. Load
  // the permission catalog once per page visit, then let _paRender repaint the
  // shared tab body in place on subsequent edits and tab switches.
  _paTab = (_dirTab === 'templates') ? 'templates' : 'users';
  if (_dirPermsLoaded) { _paRender(); return; }
  body.innerHTML = cxSkeleton(6);
  _paLoad()
    .then(() => { _dirPermsLoaded = true; _paRender(); })
    .catch(err => { body.innerHTML = cxError({ message: 'Could not load permission data: ' + (err.message || err), retry: 'renderDirectoryTabBody()' }); });
}

function renderAdminOverview() {
  const root = document.getElementById('admin-overview-content');
  if (!root || !currentRoleUser) return;
  if (currentRoleUser.role !== 'admin') { root.innerHTML = `<div class="docs-empty"><h3>Admins only</h3></div>`; return; }
  root.innerHTML = _adminOverviewHTML();
}

// ==========================================================================
// ADMIN PORTAL — Template Management & Deployment
// ==========================================================================
function renderAdminPortal() {
  const root = document.getElementById('admin-content');
  if (!root || !currentRoleUser) return;
  if (currentRoleUser.role !== 'admin') {
    root.innerHTML = `<div class="docs-empty"><h3>Admins only</h3><p>This area is restricted to Admin role.</p></div>`;
    return;
  }
  const tabs = [
    { id: 'templates',       label: 'Activity Templates' },
    { id: 'testcases',       label: 'Test Items' },
    { id: 'locations',       label: 'Locations' },
    { id: 'directory',       label: 'Directory' },
    { id: 'fieldconfig',     label: 'Field Config' },
    { id: 'activitymanager', label: 'Activity Manager' },
    { id: 'overview',        label: 'Overview' },
  ];
  root.innerHTML = `
    <div class="admin-tabs">
      ${tabs.map(t => `<button class="admin-tab${_adminTab === t.id ? ' active' : ''}" onclick="setAdminTab('${t.id}')">${t.label}</button>`).join('')}
    </div>
    <div id="admin-tab-body"></div>
  `;
  renderAdminTabBody();
  // Also refresh standalone admin pages
  renderAdminTemplates();
  renderAdminOverview();
}

function setAdminTab(tab) {
  _adminTab = tab;
  const labelMap = { templates:'Activity Templates', testcases:'Test Items', locations:'Locations', directory:'Directory', fieldconfig:'Field Config', activitymanager:'Activity Manager', overview:'Overview' };
  document.querySelectorAll('.admin-tab').forEach(el => {
    el.classList.toggle('active', el.textContent.trim() === labelMap[tab]);
  });
  renderAdminTabBody();
}

function renderAdminTabBody() {
  const body = document.getElementById('admin-tab-body');
  if (!body) return;
  if (_adminTab === 'templates')           body.innerHTML = _adminTemplatesHTML();
  else if (_adminTab === 'testcases')      body.innerHTML = _adminTestItemsHTML();
  else if (_adminTab === 'locations')      body.innerHTML = _adminLocationsHTML();
  else if (_adminTab === 'directory')      { body.innerHTML = _adminDirectoryHTML(); _loadDirectoryUsers(); }
  else if (_adminTab === 'fieldconfig')    body.innerHTML = _adminFieldConfigHTML();
  else if (_adminTab === 'activitymanager') { body.innerHTML = _adminActivityManagerHTML(); }
  else body.innerHTML = _adminOverviewHTML();
}

function _adminOverviewHTML() {
  const nDeployments = DEPLOYMENTS.length;
  const nTemplates = TEMPLATES.length;
  const nItems = TI.length;
  const nLocs = LOCS.length;
  return `
    <div class="kpi-grid kpi-grid-mini" style="margin-bottom:28px;">
      <div class="kpi-card kpi-mini"><div class="kpi-label">Activity Templates</div><div class="kpi-value">${nTemplates}</div></div>
      <div class="kpi-card kpi-mini"><div class="kpi-label">Active Deployments</div><div class="kpi-value">${nDeployments}</div></div>
      <div class="kpi-card kpi-mini"><div class="kpi-label">Test Items</div><div class="kpi-value">${nItems}</div></div>
      <div class="kpi-card kpi-mini"><div class="kpi-label">Locations</div><div class="kpi-value">${nLocs}</div></div>
    </div>
    <div class="admin-section">
      <div class="admin-section-head">
        <div><div class="admin-section-title">Recent Deployments</div></div>
      </div>
      <div class="data-card">
        <table class="data-table">
          <thead><tr><th>Template</th><th>Locations</th><th>Test Cases</th><th>Deployed By</th><th>When</th></tr></thead>
          <tbody>
            ${DEPLOYMENTS.length ? DEPLOYMENTS.map(d => {
              const totalTC = d.locations.reduce((sum, l) => sum + l.applicable.length, 0);
              return `<tr>
                <td><span class="cell-name">${escapeHtml(d.templateName)}</span></td>
                <td>${d.locations.map(l => `<span class="tag" style="margin-right:4px">${escapeHtml(l.code)}</span>`).join('')}</td>
                <td><b>${totalTC}</b> applicable across ${d.locations.length} locations</td>
                <td>${escapeHtml(d.deployedBy)}</td>
                <td>${dateAgo(d.deployedAt)}</td>
              </tr>`;
            }).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--gray-500);padding:24px;">No deployments yet</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>
  `;
}

function _adminTemplatesHTML() {
  return `
    <div class="admin-section">
      <div class="admin-section-head">
        <div>
          <div class="admin-section-title">Activity Templates</div>
          <p class="section-sub">Create reusable templates that can be deployed across multiple locations</p>
        </div>
        <button class="admin-action-btn" onclick="openNewTemplateModal()">+ New Template</button>
      </div>
      ${TEMPLATES.length ? `<div class="template-grid">
        ${TEMPLATES.map(tpl => `
          <div class="template-card">
            <div class="template-card-head" style="display:flex;align-items:center;justify-content:space-between;">
              <span class="template-tag">${escapeHtml(tpl.subsystem)}</span>
              <div style="display:flex;gap:6px;">
                <button class="form-secondary" style="font-size:11px;padding:3px 8px;" onclick="editTemplate('${tpl.id}')">Edit</button>
                <button class="admin-action-btn" style="font-size:11px;padding:3px 8px;" onclick="openDeployModal('${tpl.id}')">Deploy</button>
                <button class="form-secondary" style="font-size:11px;padding:3px 8px;color:var(--red-600);" onclick="deleteTemplate('${tpl.id}')">Delete</button>
              </div>
            </div>
            <div class="template-card-name" style="cursor:pointer;" onclick="openDeployModal('${tpl.id}')">${escapeHtml(tpl.name)}</div>
            <div class="template-card-sub">${escapeHtml(tpl.description || '')}</div>
            <div class="template-card-stats">
              <span><b>${tpl.testCases.length}</b> test cases</span>
              <span><b>${DEPLOYMENTS.filter(d => d.templateId === tpl.id).length}</b> deployments</span>
            </div>
          </div>
        `).join('')}
      </div>` : `<div class="data-card" style="padding:32px;text-align:center;color:var(--gray-500);">No templates yet — click + New Template to create one.</div>`}
    </div>
  `;
}

function _adminTestItemsHTML() {
  return `
    <div class="admin-section">
      <div class="admin-section-head">
        <div>
          <div class="admin-section-title">Import Test Items</div>
          <p class="section-sub">Upload a CSV to add new test cases or update existing ones — status is fully controlled by your file.</p>
        </div>
        <button class="admin-action-btn" onclick="downloadImportTemplate()">↓ Download Template</button>
      </div>
      <div class="data-card" style="padding:24px;text-align:center;">
        <p style="font-size:13px;color:var(--gray-700);margin-bottom:16px;">
          Fill in the template CSV, then upload it here. You'll see a full review before anything is saved.
        </p>
        <label style="cursor:pointer;">
          <input type="file" accept=".csv" onchange="handleImportFile(this)" style="display:none">
          <div class="admin-action-btn" style="display:inline-block;cursor:pointer;">${icon('folder')} Choose CSV to Import</div>
        </label>
        <p style="font-size:11px;color:var(--gray-500);margin-top:12px;">
          Valid Status values: Future · Not Started · In Progress · Pass · Fail · Partial · Blocked
        </p>
      </div>
      <div style="margin-top:20px;">
        <div style="font-size:13px;font-weight:600;margin-bottom:8px;color:var(--gray-700);">${TI.length} test items loaded</div>
      </div>
    </div>
  `;
}

function _adminLocationsHTML() {
  const tree = _buildLocTree(LOCS);
  return `
    <div class="admin-section">
      <div class="admin-section-head">
        <div>
          <div class="admin-section-title">Location Hierarchy</div>
          <p class="section-sub">Define phases and stations — used across field intake, templates, and reporting</p>
        </div>
        <div style="display:flex;gap:8px;align-items:center;">
          <button class="form-secondary" id="loc-delete-btn" style="display:none;font-size:12px;padding:6px 12px;color:var(--red-600);" onclick="bulkDeleteLocations()">Delete Selected</button>
          <label style="cursor:pointer;">
            <input type="file" accept=".csv" onchange="handleLocationImport(this)" style="display:none">
            <div class="admin-action-btn-secondary" style="display:inline-block;cursor:pointer;padding:9px 16px;font-size:13px;font-weight:600;border:1px solid var(--gray-300);border-radius:var(--radius-sm);">↑ Import CSV</div>
          </label>
          <button class="admin-action-btn-secondary" onclick="downloadLocationTemplate()">↓ CSV Template</button>
          <button class="admin-action-btn" onclick="openAddLocationModal(null, 1)">+ Add Phase</button>
        </div>
      </div>
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;">
        <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--gray-600);cursor:pointer;">
          <input type="checkbox" id="loc-select-all" onchange="locToggleSelectAll(this.checked)"> Select all
        </label>
        <span id="loc-selected-count" style="font-size:12px;color:var(--gray-500);"></span>
      </div>
      <div class="loc-tree">
        ${tree.length ? tree.map(n => _renderLocNode(n, 0)).join('') : `<div class="data-card" style="padding:32px;text-align:center;color:var(--gray-500);">No locations yet — click + Add Phase to start, or import a CSV.</div>`}
      </div>
    </div>
  `;
}

function _buildLocTree(locs) {
  const map = {};
  locs.forEach(l => { map[l.id] = { ...l, children: [] }; });
  const roots = [];
  locs.forEach(l => {
    if (l.parent_id && map[l.parent_id]) map[l.parent_id].children.push(map[l.id]);
    else roots.push(map[l.id]);
  });
  return roots;
}

function _renderLocNode(node, depth) {
  const indent = depth * 28;
  const levelClass = `loc-level-${Math.min(node.level, 3)}`;
  return `
    <div class="${levelClass}" style="margin-left:${indent}px;">
      <div class="loc-node-row">
        <div class="loc-node-name">
          <input type="checkbox" class="loc-cb" data-id="${node.id}" onchange="locUpdateSelection()" style="margin-right:6px;">
          ${depth > 0 ? '<span class="loc-indent">└─</span>' : ''}
          <span class="loc-level-badge">L${node.level}</span>
          ${escapeHtml(node.name)}
        </div>
        <div class="loc-node-actions">
          <button class="form-secondary" style="font-size:11px;padding:3px 8px;" onclick="openAddLocationModal('${node.id}', ${node.level + 1})">+ Sub-level</button>
          <button class="form-secondary" style="font-size:11px;padding:3px 8px;" onclick="openEditLocationModal('${node.id}')">Edit</button>
          <button class="form-secondary" style="font-size:11px;padding:3px 8px;color:var(--red-600);" onclick="deleteLocation('${node.id}')">Delete</button>
        </div>
      </div>
    </div>
    ${node.children.map(c => _renderLocNode(c, depth + 1)).join('')}
  `;
}

function locToggleSelectAll(checked) {
  document.querySelectorAll('.loc-cb').forEach(cb => { cb.checked = checked; });
  locUpdateSelection();
}

function locUpdateSelection() {
  const checked = document.querySelectorAll('.loc-cb:checked');
  const btn = document.getElementById('loc-delete-btn');
  const count = document.getElementById('loc-selected-count');
  if (btn) btn.style.display = checked.length ? 'inline-block' : 'none';
  if (count) count.textContent = checked.length ? `${checked.length} selected` : '';
}

async function bulkDeleteLocations() {
  if (typeof uiCan === 'function' && !uiCan('locations', 'delete')) { toast('You do not have permission to delete locations', 'error'); return; }
  const checked = [...document.querySelectorAll('.loc-cb:checked')];
  if (!checked.length) return;
  const ids = checked.map(cb => cb.dataset.id);
  // Warn if any selected node still has children not also selected
  const unselectedChildren = LOCS.filter(l => l.parent_id && ids.includes(l.parent_id) && !ids.includes(l.id));
  if (unselectedChildren.length) {
    toast(`Some selected locations have sub-locations not selected. Select all children too, or delete them first.`, 'error');
    return;
  }
  if (!await cxConfirm(`Delete ${ids.length} location${ids.length > 1 ? 's' : ''}? This cannot be undone.`)) return;

  // Delete children-first order (deepest level first)
  const ordered = ids.slice().sort((a, b) => {
    const la = LOCS.find(l => l.id === a)?.level || 0;
    const lb = LOCS.find(l => l.id === b)?.level || 0;
    return lb - la;
  });

  let failed = 0;
  for (const id of ordered) {
    const { error } = await _sb.from('locations').delete().eq('id', id);
    if (error) { console.error('Delete failed for', id, error.message); failed++; }
    else { const i = LOCS.findIndex(l => l.id === id); if (i !== -1) LOCS.splice(i, 1); }
  }

  if (failed) toast(`Deleted ${ids.length - failed}, failed ${failed}`, 'warn');
  else toast(`Deleted ${ids.length} location${ids.length > 1 ? 's' : ''}`, 'success');
  renderAdminTabBody();
}

// ==========================================================================
// LOCATION MANAGEMENT
// ==========================================================================
function openAddLocationModal(parentId, level) {
  const parentName = parentId ? (LOCS.find(l => l.id === parentId)?.name || '') : null;
  modal({
    title: parentId ? `Add Sub-level under "${parentName}"` : 'Add Phase (Level 1)',
    size: 'small',
    body: `
      <div class="form-field">
        <label>Name</label>
        <input type="text" id="loc-name" class="form-input" placeholder="${level === 1 ? 'e.g. Phase 0' : 'e.g. W40 Millbrae'}">
      </div>
      <div class="form-field" style="margin-top:12px;">
        <label>Sort Order <span style="font-weight:400;color:var(--gray-500);">(optional, lower = first)</span></label>
        <input type="number" id="loc-sort" class="form-input" value="0" min="0">
      </div>
    `,
    footer: `
      <button class="form-secondary" onclick="closeModal()">Cancel</button>
      <button class="form-submit" onclick="saveNewLocation('${parentId || ''}', ${level})">Add</button>
    `,
  });
  setTimeout(() => document.getElementById('loc-name')?.focus(), 50);
}

async function saveNewLocation(parentId, level) {
  if (typeof uiCan === 'function' && !uiCan('locations', 'create')) { toast('You do not have permission to add locations', 'error'); return; }
  const name = document.getElementById('loc-name').value.trim();
  const sort  = parseInt(document.getElementById('loc-sort').value) || 0;
  if (!name) { toast('Name is required', 'error'); return; }
  const id = 'loc-' + Date.now();
  const { error } = await _sb.from('locations').insert({
    id, name, parent_id: parentId || null, level, sort_order: sort,
  });
  if (error) { toast('Save failed: ' + error.message, 'error'); return; }
  LOCS.push({ id, name, parent_id: parentId || null, level, sort_order: sort });
  closeModal();
  toast(`Added: ${name}`, 'success');
  renderAdminTabBody();
}

function openEditLocationModal(id) {
  const loc = LOCS.find(l => l.id === id);
  if (!loc) return;
  modal({
    title: 'Edit Location',
    size: 'small',
    body: `
      <div class="form-field">
        <label>Name</label>
        <input type="text" id="eloc-name" class="form-input" value="${escapeHtml(loc.name)}">
      </div>
      <div class="form-field" style="margin-top:12px;">
        <label>Sort Order</label>
        <input type="number" id="eloc-sort" class="form-input" value="${loc.sort_order || 0}" min="0">
      </div>
    `,
    footer: `
      <button class="form-secondary" onclick="closeModal()">Cancel</button>
      <button class="form-submit" onclick="saveEditLocation('${id}')">Save</button>
    `,
  });
  setTimeout(() => document.getElementById('eloc-name')?.focus(), 50);
}

async function saveEditLocation(id) {
  if (typeof uiCan === 'function' && !uiCan('locations', 'edit')) { toast('You do not have permission to edit locations', 'error'); return; }
  const loc  = LOCS.find(l => l.id === id);
  if (!loc) return;
  const name = document.getElementById('eloc-name').value.trim();
  const sort = parseInt(document.getElementById('eloc-sort').value) || 0;
  if (!name) { toast('Name is required', 'error'); return; }
  const { error } = await _sb.from('locations').update({ name, sort_order: sort }).eq('id', id);
  if (error) { toast('Save failed: ' + error.message, 'error'); return; }
  loc.name = name; loc.sort_order = sort;
  closeModal();
  toast(`Saved: ${name}`, 'success');
  renderAdminTabBody();
}

async function deleteLocation(id) {
  if (typeof uiCan === 'function' && !uiCan('locations', 'delete')) { toast('You do not have permission to delete locations', 'error'); return; }
  const loc = LOCS.find(l => l.id === id);
  if (!loc) return;
  const children = LOCS.filter(l => l.parent_id === id);
  if (children.length) {
    toast(`Remove the ${children.length} sub-location(s) under "${loc.name}" first`, 'error');
    return;
  }
  if (!await cxConfirm(`Delete "${loc.name}"? This cannot be undone.`)) return;
  const { error } = await _sb.from('locations').delete().eq('id', id);
  if (error) { toast('Delete failed: ' + error.message, 'error'); return; }
  LOCS.splice(LOCS.indexOf(loc), 1);
  toast(`Deleted: ${loc.name}`, 'success');
  renderAdminTabBody();
}

function downloadLocationTemplate() {
  const csv = 'Level,Name,ParentName\n1,Phase 0,\n1,Phase 1,\n1,Phase 2,\n2,W40 Millbrae,Phase 0\n2,M10,Phase 2';
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([csv], { type:'text/csv' }));
  a.download = 'Locations_Template.csv';
  a.click();
  URL.revokeObjectURL(a.href);
}

let _locImportRows = [];

function handleLocationImport(input) {
  const file = input.files[0]; if (!file) return; input.value = '';
  file.text().then(text => {
    const rows = parseCSVGeneric(text);
    _locImportRows = rows.filter(r => r.Level && r.Name).map(r => ({
      level:      parseInt(r.Level) || 1,
      name:       r.Name.trim(),
      parentName: (r.ParentName || '').trim(),
    }));
    if (!_locImportRows.length) { toast('No valid rows found — need Level, Name, ParentName columns', 'error'); return; }
    modal({
      title: 'Review Location Import',
      size: 'medium',
      body: `
        <p style="font-size:13px;color:var(--gray-700);margin-bottom:16px;">${_locImportRows.length} locations will be imported. Existing locations with the same name + level are skipped.</p>
        <div class="data-card" style="padding:0;max-height:300px;overflow-y:auto;">
          <table class="data-table">
            <thead><tr><th>Level</th><th>Name</th><th>Parent</th></tr></thead>
            <tbody>
              ${_locImportRows.map(r => `<tr>
                <td><span class="loc-level-badge">L${r.level}</span></td>
                <td>${escapeHtml(r.name)}</td>
                <td>${escapeHtml(r.parentName) || '—'}</td>
              </tr>`).join('')}
            </tbody>
          </table>
        </div>
      `,
      footer: `
        <button class="form-secondary" onclick="closeModal()">Cancel</button>
        <button class="form-submit" onclick="executeLocationImport()">Import ${_locImportRows.length} Locations</button>
      `,
    });
  });
}

async function executeLocationImport() {
  if (typeof uiCan === 'function' && !uiCan('locations', 'import')) { toast('You do not have permission to import locations', 'error'); return; }
  // Build in-order: parents first (sort by level ascending)
  const sorted = [..._locImportRows].sort((a, b) => a.level - b.level);
  const nameToId = {};
  // Seed from existing LOCS
  LOCS.forEach(l => { nameToId[`${l.level}:${l.name}`] = l.id; });

  let added = 0;
  for (const row of sorted) {
    const key = `${row.level}:${row.name}`;
    if (nameToId[key]) continue; // already exists
    const parentKey = row.parentName ? `${row.level - 1}:${row.parentName}` : null;
    const parentId  = parentKey ? (nameToId[parentKey] || null) : null;
    const id = 'loc-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6);
    const { error } = await _sb.from('locations').insert({ id, name: row.name, parent_id: parentId, level: row.level, sort_order: 0 });
    if (error) { toast('Import error on "' + row.name + '": ' + error.message, 'error'); continue; }
    LOCS.push({ id, name: row.name, parent_id: parentId, level: row.level, sort_order: 0 });
    nameToId[key] = id;
    added++;
  }
  closeModal();
  toast(`Imported ${added} location(s)`, 'success');
  renderAdminTabBody();
}

// ==========================================================================
// TEST ITEM CSV IMPORT
// ==========================================================================
let _importPendingRows = [];

function downloadImportTemplate() {
  const headers = ['Phase','Location','Subsystem','Activity','TestCategory','TestCaseCode','TestName','TestSection','TestProcedure','TestPhase','Status','ActivityID','PlannedDate','Weight','Notes','TestReport'];
  const example = ['Phase 2','W40','ATS','ATS SAT','Hardware SAT','HW-SAT-XX','Example Test Name','Section 1','1. Do step one. 2. Verify result.','SAT','Future','ACT-001','2025-06-01','1','Optional notes','https://docs.example.com/report'];
  const csv = headers.join(',') + '\n' + example.map(v => `"${v}"`).join(',');
  const blob = new Blob([csv], { type: 'text/csv' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'TestItems_Import_Template.csv';
  a.click();
  URL.revokeObjectURL(a.href);
}

function splitCSVLine(line) {
  const result = []; let cur = ''; let inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') { if (inQ && line[i+1] === '"') { cur += '"'; i++; } else { inQ = !inQ; } }
    else if (c === ',' && !inQ) { result.push(cur); cur = ''; }
    else { cur += c; }
  }
  result.push(cur);
  return result;
}

function parseCSVGeneric(text) {
  const lines = text.replace(/\r\n/g,'\n').replace(/\r/g,'\n').split('\n').filter(l => l.trim());
  if (lines.length < 2) return [];
  const headers = splitCSVLine(lines[0]).map(h => h.trim().replace(/^"|"$/g,''));
  return lines.slice(1).map(line => {
    const vals = splitCSVLine(line);
    const obj = {};
    headers.forEach((h, i) => { obj[h] = (vals[i] || '').trim().replace(/^"|"$/g,''); });
    return obj;
  });
}

function parseCSV(text) {
  return parseCSVGeneric(text).filter(r => (r.TestCaseCode && r.TestCaseCode.trim()) || (r.TestName && r.TestName.trim()));
}

function parseImportDate(val) {
  if (!val || !val.trim()) return null;
  const d = new Date(val.trim());
  return isNaN(d.getTime()) ? null : d.toISOString();
}

function importStatusBadge(status) {
  const s = (status || '').toLowerCase().trim();
  if (s === 'pass' || s === 'passed') return 'passed';
  if (s === 'fail' || s === 'failed') return 'failed';
  if (s === 'blocked') return 'pending';
  if (s === 'in progress' || s === 'in_progress' || s === 'partial') return 'progress';
  return 'neutral';
}

// Returns { exact: bool, name: string } or null if no match at all
function _matchLoc(value, level, parentId) {
  if (!value || !LOCS.length) return null;
  const v = value.toLowerCase().trim();
  const pool = LOCS.filter(l => l.level === level && (parentId == null || l.parent_id === parentId));
  const exact = pool.find(l => l.name.toLowerCase() === v);
  if (exact) return { exact: true, name: exact.name, id: exact.id };
  // partial: input is contained in a known name or vice-versa
  const partial = pool.find(l => l.name.toLowerCase().includes(v) || v.includes(l.name.toLowerCase()));
  if (partial) return { exact: false, name: partial.name, id: partial.id };
  return null;
}

async function handleImportFile(input) {
  const file = input.files[0];
  if (!file) return;
  input.value = '';
  let text;
  try { text = await file.text(); } catch(e) { toast('Could not read file', 'error'); return; }

  const rows = parseCSV(text);
  if (rows.length === 0) {
    toast('No valid rows found — make sure the TestCaseCode or TestName column is filled in.', 'warn');
    return;
  }

  _importPendingRows = rows;

  // Location validation (only if master list is loaded)
  const locWarnings = [];
  if (LOCS.length > 0) {
    rows.forEach(r => {
      const label = r.TestCaseCode || r.TestName || '';
      const phaseMatch = _matchLoc(r.Phase || '', 1, null);
      const locMatch   = phaseMatch ? _matchLoc(r.Location || '', 2, phaseMatch.id) : null;

      if (r.Phase && !phaseMatch) {
        locWarnings.push({ id: label, field: 'Phase', value: r.Phase, suggestion: null });
      } else if (r.Phase && phaseMatch && !phaseMatch.exact) {
        locWarnings.push({ id: label, field: 'Phase', value: r.Phase, suggestion: phaseMatch.name });
      }
      if (r.Location && phaseMatch && !locMatch) {
        locWarnings.push({ id: label, field: 'Location', value: r.Location, suggestion: null });
      } else if (r.Location && locMatch && !locMatch.exact) {
        locWarnings.push({ id: label, field: 'Location', value: r.Location, suggestion: locMatch.name });
      }
    });
  }

  const warnHTML = locWarnings.length > 0 ? `
    <div style="margin-bottom:16px;padding:14px;border:1px solid #d97706;border-radius:8px;background:rgba(217,119,6,0.05);">
      <div style="font-weight:600;font-size:13px;color:#d97706;margin-bottom:10px;">${icon('alert')} ${locWarnings.length} location name${locWarnings.length > 1 ? 's' : ''} don't match the master list</div>
      <div style="max-height:140px;overflow-y:auto;">
        <table class="data-table">
          <thead><tr><th>Test Case</th><th>Field</th><th>In CSV</th><th>Master List Says</th></tr></thead>
          <tbody>
            ${locWarnings.map(w => `<tr>
              <td style="font-size:11px;font-weight:600;">${escapeHtml(w.id)}</td>
              <td style="font-size:11px;">${escapeHtml(w.field)}</td>
              <td style="font-size:11px;color:#dc2626;">${escapeHtml(w.value)}</td>
              <td style="font-size:11px;color:#16a34a;">${w.suggestion ? escapeHtml(w.suggestion) : '<em style="color:var(--gray-400)">no match found</em>'}</td>
            </tr>`).join('')}
          </tbody>
        </table>
      </div>
      <p style="font-size:11px;color:var(--gray-600);margin-top:8px;">You can still import — mismatched names will be stored as-is. Fix the CSV or update the master locations list.</p>
    </div>` : '';

  const newHTML = `
    <div style="padding:16px;border:1px solid var(--good);border-radius:8px;background:rgba(0,135,90,0.05);">
      <div style="font-weight:600;font-size:14px;color:var(--good);margin-bottom:12px;">
        ✓ ${rows.length} new test case${rows.length > 1 ? 's' : ''} to add
      </div>
      <div style="max-height:200px;overflow-y:auto;">
        <table class="data-table">
          <thead><tr><th>Test Case Code</th><th>Test Name</th><th>Phase</th><th>Location</th><th>Status</th></tr></thead>
          <tbody>
            ${rows.map(r => `<tr>
              <td style="font-size:12px;font-weight:600;">${escapeHtml(r.TestCaseCode || '')}</td>
              <td style="font-size:12px;">${escapeHtml(r.TestName || '')}</td>
              <td><span class="tag tag-phase">${escapeHtml(r.Phase || '')}</span></td>
              <td style="font-size:12px;">${escapeHtml(r.Location || '')}</td>
              <td><span class="badge badge-${importStatusBadge(r.Status||'Future')}">${escapeHtml(r.Status||'Future')}</span></td>
            </tr>`).join('')}
          </tbody>
        </table>
      </div>
    </div>`;

  modal({
    title: 'Review Import',
    sub: `${rows.length} row${rows.length !== 1 ? 's' : ''} — all new`,
    size: 'large',
    body: warnHTML + newHTML,
    footer: `
      <button class="form-secondary" onclick="closeModal()">Cancel</button>
      <button class="form-submit" id="do-import-btn" onclick="executeImport()">
        Import ${rows.length} test case${rows.length !== 1 ? 's' : ''}
      </button>`,
  });
}

async function executeImport() {
  if (typeof uiCan === 'function' && !uiCan('test_register', 'import')) { toast('You do not have permission to import test items.', 'error'); return; }
  if (!_importPendingRows.length || !_sb) return;
  const btn = document.getElementById('do-import-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Importing…'; }

  const dbRows = _importPendingRows.map(r => ({
    phase:          r.Phase         || null,
    location:       r.Location      || null,
    subsystem:      r.Subsystem     || null,
    activity:       r.Activity      || null,
    test_category:  r.TestCategory  || null,
    test_case_code: r.TestCaseCode  || '',
    test_name:      r.TestName      || null,
    test_procedure: r.TestProcedure || null,
    test_phase:     r.TestPhase     || null,
    status:         r.Status        || 'Future',
    activity_id:    r.ActivityID    || null,
    completed_date: parseImportDate(r.PlannedDate),
    weight:         1, // legacy column — real weight lives in test_case_weights
    notes:          r.Notes         || null,
    synced_at:      new Date().toISOString(),
  }));

  try {
    const { error } = await _sb.from('test_items').insert(dbRows);
    if (error) throw error;
    await loadTestItems();
    closeModal();
    _importPendingRows = [];
    toast(`Imported ${dbRows.length} test case${dbRows.length !== 1 ? 's' : ''} successfully!`, 'success');
    renderAdminPortal();
    renderAdminTemplates();
  } catch (err) {
    console.error('Import failed:', err);
    toast(`Import failed: ${err.message}`, 'error');
    if (btn) { btn.disabled = false; btn.textContent = `Import ${dbRows.length} test cases`; }
  }
}

let _deploySelections = []; // [{ locId, locName, phase, location, tcCodes:[] }]
let _deployTplId = null;

function openDeployModal(templateId) {
  const tpl = TEMPLATES.find(t => t.id === templateId);
  if (!tpl) return;
  _deployTplId = templateId;
  _deploySelections = [];

  const phases = LOCS.filter(l => l.level === 1).sort((a,b) => a.sort_order - b.sort_order);
  const noLocs = phases.length === 0;

  modal({
    title: `Deploy: ${tpl.name}`,
    sub: `${tpl.subsystem} · ${tpl.testCases.length} test cases`,
    size: 'large',
    body: `
      ${noLocs ? `<div style="padding:12px;background:#fef3c7;border:1px solid #f59e0b;border-radius:6px;font-size:13px;margin-bottom:16px;">
        No locations in master list yet — go to Admin → Locations to add them first.
      </div>` : ''}
      <div style="display:grid;grid-template-columns:1fr 1fr auto;gap:10px;align-items:flex-end;margin-bottom:20px;padding-bottom:20px;border-bottom:1px solid var(--gray-200);">
        <div>
          <label style="font-size:11px;font-weight:600;color:var(--gray-500);display:block;margin-bottom:4px;">PHASE</label>
          <select id="dep-phase" class="form-input" onchange="deployFilterLocations()" ${noLocs ? 'disabled' : ''}>
            <option value="">Select phase…</option>
            ${phases.map(p => `<option value="${p.id}">${escapeHtml(p.name)}</option>`).join('')}
          </select>
        </div>
        <div>
          <label style="font-size:11px;font-weight:600;color:var(--gray-500);display:block;margin-bottom:4px;">LOCATION</label>
          <select id="dep-location" class="form-input" ${noLocs ? 'disabled' : ''}>
            <option value="">Select phase first…</option>
          </select>
        </div>
        <button class="admin-action-btn" onclick="deployAddLocation('${templateId}')" style="white-space:nowrap;" ${noLocs ? 'disabled' : ''}>+ Add</button>
      </div>
      <div id="deploy-selections">
        <div style="text-align:center;color:var(--gray-400);font-size:13px;padding:20px 0;">No locations added yet</div>
      </div>
    `,
    footer: `
      <button class="admin-action-btn-secondary" onclick="closeModal()">Cancel</button>
      <button class="admin-action-btn" id="dep-confirm-btn" onclick="confirmDeploy('${templateId}')">Deploy</button>
    `,
  });
}

function deployFilterLocations() {
  const phaseId = document.getElementById('dep-phase').value;
  const locSel  = document.getElementById('dep-location');
  if (!phaseId) { locSel.innerHTML = '<option value="">Select phase first…</option>'; return; }
  const children = LOCS.filter(l => l.parent_id === phaseId).sort((a,b) => a.sort_order - b.sort_order);
  locSel.innerHTML = children.length
    ? '<option value="">Select location…</option>' + children.map(l => `<option value="${l.id}">${escapeHtml(l.name)}</option>`).join('')
    : '<option value="">No locations under this phase</option>';
}

function deployAddLocation(templateId) {
  const tpl      = TEMPLATES.find(t => t.id === templateId);
  const phaseEl  = document.getElementById('dep-phase');
  const locEl    = document.getElementById('dep-location');
  const phaseId  = phaseEl.value;
  const locId    = locEl.value;
  if (!phaseId) { toast('Select a phase first', 'warn'); return; }
  if (!locId)   { toast('Select a location', 'warn'); return; }
  if (_deploySelections.find(s => s.locId === locId)) { toast('Location already added', 'warn'); return; }

  const phase = LOCS.find(l => l.id === phaseId);
  const loc   = LOCS.find(l => l.id === locId);
  _deploySelections.push({
    locId, locName: loc.name, phaseName: phase.name,
    tcCodes: tpl.testCases.map(tc => tc.code),
  });
  _renderDeploySelections(tpl);
  // Reset dropdowns
  locEl.value = '';
}

function deployRemoveLocation(locId) {
  _deploySelections = _deploySelections.filter(s => s.locId !== locId);
  const tpl = TEMPLATES.find(t => t.id === _deployTplId);
  _renderDeploySelections(tpl);
}

function _renderDeploySelections(tpl) {
  const el = document.getElementById('deploy-selections');
  if (!el) return;
  if (!_deploySelections.length) {
    el.innerHTML = '<div style="text-align:center;color:var(--gray-400);font-size:13px;padding:20px 0;">No locations added yet</div>';
    return;
  }

  // Group test cases by section (for multi-section templates)
  const sectionMap = new Map();
  for (const tc of tpl.testCases) {
    const sec = tc.section ?? '';
    if (!sectionMap.has(sec)) sectionMap.set(sec, []);
    sectionMap.get(sec).push(tc);
  }
  const sections = [...sectionMap.entries()]; // [[sectionTitle, [tc,...]], ...]
  const isMultiSection = sections.length > 1 || (sections.length === 1 && sections[0][0] !== '');

  function _tcCheckboxes(si, s, cases) {
    return cases.map(tc => `
      <label style="display:flex;align-items:center;gap:5px;font-size:12px;background:var(--white);border:1px solid var(--gray-200);border-radius:4px;padding:4px 8px;cursor:pointer;">
        <input type="checkbox" data-si="${si}" data-tc="${escapeHtml(tc.code)}" ${s.tcCodes.includes(tc.code) ? 'checked' : ''}
          onchange="_deployToggleTc(${si},'${tc.code}',this.checked)">
        <span style="font-weight:600;">${escapeHtml(tc.code)}</span>${tc.name ? `<span style="color:var(--gray-500);margin-left:3px;">— ${escapeHtml(tc.name)}</span>` : ''}
      </label>
    `).join('');
  }

  el.innerHTML = _deploySelections.map((s, si) => `
    <div style="border:1px solid var(--gray-200);border-radius:8px;margin-bottom:10px;overflow:hidden;">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:10px 14px;background:var(--gray-50);border-bottom:1px solid var(--gray-200);">
        <div style="font-weight:600;font-size:13px;">
          <span style="color:var(--gray-500);font-weight:400;">${escapeHtml(s.phaseName)} /</span> ${escapeHtml(s.locName)}
          <span style="font-size:11px;color:var(--gray-500);font-weight:400;margin-left:8px;" id="dep-count-${s.locId}">${s.tcCodes.length} of ${tpl.testCases.length} test cases</span>
        </div>
        <button onclick="deployRemoveLocation('${s.locId}')" style="font-size:11px;color:var(--red-600);background:none;border:none;cursor:pointer;padding:2px 6px;">${icon('x')} Remove</button>
      </div>
      ${isMultiSection
        ? sections.map(([secTitle, cases]) => `
            <div style="border-bottom:1px solid var(--gray-100);">
              <div style="padding:7px 14px 4px;font-size:11px;font-weight:700;color:var(--gray-500);letter-spacing:.05em;text-transform:uppercase;background:var(--gray-50);">
                ${secTitle ? escapeHtml(secTitle) : 'General'}
              </div>
              <div style="padding:8px 14px 10px;display:flex;flex-wrap:wrap;gap:6px;">
                ${_tcCheckboxes(si, s, cases)}
              </div>
            </div>
          `).join('')
        : `<div style="padding:10px 14px;display:flex;flex-wrap:wrap;gap:6px;">${_tcCheckboxes(si, s, sections[0]?.[1] || [])}</div>`
      }
    </div>
  `).join('');
}

function _deployToggleTc(si, tcCode, checked) {
  if (checked) { if (!_deploySelections[si].tcCodes.includes(tcCode)) _deploySelections[si].tcCodes.push(tcCode); }
  else { _deploySelections[si].tcCodes = _deploySelections[si].tcCodes.filter(c => c !== tcCode); }
  const tpl = TEMPLATES.find(t => t.id === _deployTplId);
  const s = _deploySelections[si];
  const el = document.getElementById(`dep-count-${s.locId}`);
  if (el) el.textContent = `${s.tcCodes.length} of ${tpl.testCases.length} test cases`;
}

async function confirmDeploy(templateId) {
  if (typeof uiCan === 'function' && !uiCan('templates', 'deploy')) { toast('You do not have permission to deploy templates', 'error'); return; }
  const tpl = TEMPLATES.find(t => t.id === templateId);
  if (!_deploySelections.length) { toast('Add at least one location', 'warn'); return; }
  const empty = _deploySelections.filter(s => !s.tcCodes.length);
  if (empty.length) { toast(`"${empty[0].locName}" has no test cases selected`, 'warn'); return; }

  // Disable button while saving
  const btn = document.getElementById('dep-confirm-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Deploying…'; }

  const depId   = 'dep-' + Date.now();
  const now     = new Date().toISOString();
  const actor   = currentRoleUser?.name || 'admin';
  const totalLocs = _deploySelections.length;

  try {
    // ── 1. Build test_items rows ──────────────────────────────────────────────
    const rows = [];
    for (const s of _deploySelections) {
      for (const tcCode of s.tcCodes) {
        const tc = tpl.testCases.find(t => t.code === tcCode);
        rows.push({
          test_id:        `${depId}-${s.locId}-${tcCode}`,
          phase:          s.phaseName,
          location:       s.locName,
          subsystem:      tpl.subsystem,
          activity:       tpl.name,
          test_category:  null,
          test_case_code: tcCode,
          test_name:      tc?.name || tcCode,
          test_procedure: tc?.procedure || '',
          test_section:   tc?.section   || '',
          scope_type:     (tc?.scopeType || tc?.scope_type || 'static') === 'dynamic' ? 'dynamic' : 'static',
          status:         'Not Started',
          weight:         1, // legacy per-row column; real weight lives in test_case_weights
          synced_at:      now,
        });
      }
    }

    if (!rows.length) { toast('No test cases to deploy', 'warn'); return; }

    // ── 2. Insert test_items into Supabase in batches of 50 ──────────────────
    const BATCH = 50;
    for (let i = 0; i < rows.length; i += BATCH) {
      await _dbInsert('test_items', rows.slice(i, i + BATCH));
    }

    // ── 2b. Clone any template-attached PDFs once per deployed test case ──
    try {
      const clonedCount = await _formsCloneTemplateForDeployment(templateId, depId, _deploySelections, tpl);
      if (clonedCount) console.log(`[confirmDeploy] cloned ${clonedCount} form copies for deployment ${depId}`);
    } catch (e) { console.warn('[confirmDeploy] form clone failed:', e.message); }

    // ── 3. Update in-memory DEPLOYMENTS so the overview reflects the new entry
    const enabledLocs = _deploySelections.map(s => ({
      code: s.locId, name: s.locName, phase: s.phaseName, applicable: s.tcCodes,
    }));
    DEPLOYMENTS.unshift({
      id: depId, templateId, templateName: tpl.name,
      deployedBy: actor, deployedAt: now, locations: enabledLocs,
    });

    // ── 5. Reload TI from Supabase so the Test Register shows the new items ──
    await loadTestItems();
    await loadAssetData();

    // ── 6. Auto-create generic child assets defined in the template ───────────
    for (const s of _deploySelections) {
      for (const tcCode of s.tcCodes) {
        const tc = tpl.testCases.find(t => t.code === tcCode);
        if (!tc?.assets?.trim()) continue;
        const parentId  = `${depId}-${s.locId}-${tcCode}`;
        const parentRow = TI.find(r => String(r.TestID) === parentId);
        if (!parentRow) continue;
        const assetNames = tc.assets.split(',').map(a => a.trim()).filter(Boolean);
        for (const aName of assetNames) {
          try {
            let [assetRow] = await _dbUpsert('assets', [{
              name:            aName,
              device_type:     'Generic',
              location:        s.locName       || null,
              subsystem:       tpl.subsystem   || null,
              location_prefix: null,
              import_batch_id: null,
            }], 'name,location,subsystem');
            if (!assetRow) assetRow = ASSETS.find(a => a.name === aName && (a.location||'') === (s.locName||'') && (a.subsystem||'') === (tpl.subsystem||''));
            if (!assetRow) continue;
            const aIdx = ASSETS.findIndex(a => a.id === assetRow.id);
            if (aIdx >= 0) ASSETS[aIdx] = assetRow; else ASSETS.push(assetRow);
            await _assetLinkToParent(assetRow, parentRow);
          } catch(e) { console.warn('[deploy generic asset]', aName, e.message); }
        }
      }
    }

    logAudit('Deployed Template',
      `${tpl.name} → ${enabledLocs.map(l => l.name).join(', ')}`,
      `${rows.length} test cases created`);

    closeModal();
    _deploySelections = [];
    toast(`✓ Deployed ${rows.length} test case${rows.length !== 1 ? 's' : ''} across ${totalLocs} location${totalLocs !== 1 ? 's' : ''}`, 'success');
    renderAdminPortal();
    renderAdminTemplates();
    renderTestRegister();

  } catch(e) {
    console.error('[confirmDeploy]', e);
    toast('Deploy failed: ' + e.message, 'error');
    if (btn) { btn.disabled = false; btn.textContent = 'Deploy'; }
  }
}

// ==========================================================================
// TEMPLATE CREATION — Activity-based with multi-section / multi-procedure builder
// ==========================================================================
// Each section: { title:string, procedure:string, cases:[{code,name,scopeType,assets}] }
let _templateSections = [];
let _editTemplateId   = null;

// ── Conversion helpers ────────────────────────────────────────────────────────

// Flat testCases array (from Supabase) → sections array for editing.
// Old templates (no 'section' field) land in one unnamed section.
function _tplCasesToSections(testCases) {
  if (!testCases?.length) {
    return [{ title:'', procedure:'', cases:[{ code:'', name:'', scopeType:'static', assets:'' }] }];
  }
  const map = new Map();
  for (const tc of testCases) {
    const key = tc.section ?? '';
    if (!map.has(key)) map.set(key, { title: key, procedure: tc.procedure || '', cases: [] });
    map.get(key).cases.push({
      code: tc.code || '',
      name: tc.name || '',
      scopeType: (tc.scopeType || tc.scope_type || 'static') === 'dynamic' ? 'dynamic' : 'static',
      assets: tc.assets || '',
    });
  }
  return [...map.values()];
}

// Sections → flat testCases array stored in Supabase.
function _tplSectionsToTestCases(sections) {
  const out = [];
  for (const sec of sections) {
    for (const tc of sec.cases) {
      if (!tc.code.trim() && !tc.name.trim()) continue;
      out.push({
        code:      tc.code.trim(),
        name:      tc.name.trim(),
        scopeType: (tc.scopeType || 'static') === 'dynamic' ? 'dynamic' : 'static',
        assets:    (tc.assets || '').trim(),
        procedure: sec.procedure.trim(),
        section:   sec.title.trim(),
        duration:  1,
      });
    }
  }
  return out;
}

// ── Section/case HTML ─────────────────────────────────────────────────────────

function _tplSectionsHTML() {
  return _templateSections.map((sec, si) => `
    <div style="border:1px solid var(--gray-200);border-radius:8px;margin-bottom:14px;overflow:hidden;">
      <!-- Section header bar -->
      <div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--gray-100);border-bottom:1px solid var(--gray-200);">
        <span style="font-size:10px;font-weight:700;color:var(--gray-500);text-transform:uppercase;white-space:nowrap;">Section ${si + 1}</span>
        <input type="text" class="form-input" style="flex:1;font-size:13px;font-weight:600;padding:5px 10px;"
          placeholder="Section title e.g. Hardware Verification"
          value="${escapeHtml(sec.title)}"
          oninput="_templateSections[${si}].title=this.value">
        ${_templateSections.length > 1
          ? `<button onclick="removeTplSection(${si})" title="Remove section"
               style="background:none;border:none;cursor:pointer;color:var(--red-600);font-size:20px;line-height:1;padding:2px 6px;">×</button>`
          : ''}
      </div>
      <!-- Procedure for this section -->
      <div style="padding:8px 14px 10px;background:var(--gray-50);border-bottom:1px solid var(--gray-200);">
        <label style="font-size:10px;font-weight:700;color:var(--gray-500);text-transform:uppercase;display:block;margin-bottom:4px;">Test Procedure</label>
        <textarea class="form-input" rows="2" style="font-size:12px;resize:vertical;"
          placeholder="e.g. Refer to CDRL 9.04.53 Section 4. Power on system, verify comms…"
          oninput="_templateSections[${si}].procedure=this.value">${escapeHtml(sec.procedure)}</textarea>
      </div>
      <!-- Column headers -->
      <div style="display:grid;grid-template-columns:130px minmax(210px,1fr) 112px 150px 92px 32px 32px;gap:6px;padding:5px 14px;background:var(--gray-50);border-bottom:1px solid var(--gray-100);">
        <div style="font-size:10px;color:var(--gray-500);font-weight:700;text-transform:uppercase;">Code</div>
        <div style="font-size:10px;color:var(--gray-500);font-weight:700;text-transform:uppercase;">Test Case Name</div>
        <div style="font-size:10px;color:var(--gray-500);font-weight:700;text-transform:uppercase;">Scope</div>
        <div style="font-size:10px;color:var(--gray-500);font-weight:700;text-transform:uppercase;">Assets (Generic)</div>
        <div style="font-size:10px;color:var(--gray-500);font-weight:700;text-transform:uppercase;">Form PDF</div>
        <div></div><div></div>
      </div>
      <!-- Test case rows -->
      <div style="padding:8px 14px;" id="tpl-cases-${si}">${_tplCaseRowsHTML(si)}</div>
      <button class="form-secondary" style="width:calc(100% - 28px);margin:0 14px 12px;font-size:12px;"
        onclick="addTplCase(${si})">+ Add Test Case</button>
    </div>
  `).join('');
}

function _tplCaseRowsHTML(si) {
  const cases = _templateSections[si]?.cases || [];
  return cases.map((tc, ci) => `
    <div style="display:grid;grid-template-columns:130px minmax(210px,1fr) 112px 150px 92px 32px 32px;gap:6px;align-items:center;margin-bottom:5px;">
      <input type="text" class="form-input" style="font-size:12px;padding:5px 8px;" placeholder="Code e.g. DCS-01"
        value="${escapeHtml(tc.code)}" oninput="_templateSections[${si}].cases[${ci}].code=this.value">
      <input type="text" class="form-input" style="font-size:12px;padding:5px 8px;" placeholder="Test Case Name"
        value="${escapeHtml(tc.name)}" oninput="_templateSections[${si}].cases[${ci}].name=this.value">
      <select class="form-input" style="font-size:12px;padding:5px 8px;" title="Static test case or dynamic-scope test"
        onchange="_templateSections[${si}].cases[${ci}].scopeType=this.value">
        <option value="static" ${(tc.scopeType || 'static') !== 'dynamic' ? 'selected' : ''}>Static</option>
        <option value="dynamic" ${(tc.scopeType || 'static') === 'dynamic' ? 'selected' : ''}>Dynamic</option>
      </select>
      <input type="text" class="form-input" style="font-size:12px;padding:5px 8px;" placeholder="Assets e.g. MLK A, MLK B"
        value="${escapeHtml(tc.assets||'')}" oninput="_templateSections[${si}].cases[${ci}].assets=this.value"
        title="Comma-separated generic asset names auto-linked as children on deploy">
      ${_tplCaseFormCellHTML(_editTemplateId, tc, si, ci)}
      <button class="form-secondary" style="padding:4px;font-size:13px;min-width:32px;" title="Duplicate"
        onclick="dupTplCase(${si},${ci})">⧉</button>
      <button class="form-secondary" style="padding:4px;font-size:13px;min-width:32px;color:var(--bad);" title="Remove"
        onclick="removeTplCase(${si},${ci})" ${cases.length === 1 ? 'disabled' : ''}>×</button>
    </div>
  `).join('');
}

// ── Section / case actions ────────────────────────────────────────────────────

function _tplCaseFormCellHTML(templateId, tc, si, ci) {
  if (!templateId) {
    return `<button class="form-secondary tr-mini-btn" disabled title="Save the activity template before attaching PDFs" style="font-size:11px;padding:4px 6px;">Save first</button>`;
  }
  const code = String(tc?.code || '').trim();
  if (!code) {
    return `<button class="form-secondary tr-mini-btn" disabled title="Enter a test case code before attaching a PDF" style="font-size:11px;padding:4px 6px;">Code first</button>`;
  }
  const attached = _formsForTemplateTestCase(templateId, code);
  if (!attached.length) {
    return `<button class="form-secondary tr-mini-btn" title="Attach PDF template to this test case line" onclick="openAttachTemplateFormForCase('${templateId}',${si},${ci})" style="font-size:11px;padding:4px 6px;">+ PDF</button>`;
  }
  const names = attached.map(f => f.name).join(', ');
  return `
    <div style="display:flex;align-items:center;gap:4px;min-width:0;">
      <button class="admin-action-btn tr-mini-btn" title="${escapeHtml(names)}" onclick="openFormViewer('${attached[0].id}')" style="font-size:11px;padding:4px 6px;background:#dbeafe;color:#1d4ed8;border:1px solid #93c5fd;">PDF ${attached.length}</button>
      <button class="form-secondary tr-mini-btn" title="Remove PDF from this test case line" onclick="detachTemplateFormForCase('${attached[0].id}','${templateId}',${si},${ci})" style="font-size:11px;padding:4px 6px;color:var(--bad);">x</button>
    </div>
  `;
}

function addTplSection() {
  _templateSections.push({ title:'', procedure:'', cases:[{ code:'', name:'', scopeType:'static', assets:'' }] });
  document.getElementById('tpl-sections').innerHTML = _tplSectionsHTML();
}

async function removeTplSection(si) {
  if (_templateSections.length <= 1) return;
  if (!await cxConfirm(`Remove Section ${si + 1} and all its test cases?`)) return;
  _templateSections.splice(si, 1);
  document.getElementById('tpl-sections').innerHTML = _tplSectionsHTML();
}

function addTplCase(si) {
  _templateSections[si].cases.push({ code:'', name:'', scopeType:'static', assets:'' });
  document.getElementById('tpl-sections').innerHTML = _tplSectionsHTML();
}

function dupTplCase(si, ci) {
  _templateSections[si].cases.splice(ci + 1, 0, { ..._templateSections[si].cases[ci] });
  document.getElementById('tpl-sections').innerHTML = _tplSectionsHTML();
}

function removeTplCase(si, ci) {
  if (_templateSections[si].cases.length <= 1) return;
  _templateSections[si].cases.splice(ci, 1);
  document.getElementById('tpl-sections').innerHTML = _tplSectionsHTML();
}

// ── CSV ───────────────────────────────────────────────────────────────────────

function downloadTemplateCaseCSV() {
  const rows = [
    ['Section','Code','Name','Scope','Assets','Procedure'],
    ['Hardware Verification','DCS-HW-01','Network Connectivity Test','Static','','Refer to CDRL 9.04.53 Section 4'],
    ['Hardware Verification','DCS-HW-02','Server Failover Test','Dynamic','Server A,Server B','Refer to CDRL 9.04.53 Section 4'],
    ['Software Testing','DCS-SW-01','Comms Latency Test','Static','','Refer to CDRL 9.04.53 Section 5'],
    ['Software Testing','DCS-SW-02','Interface Validation','Static','','Refer to CDRL 9.04.53 Section 5'],
  ];
  const csv = rows.map(r => r.map(v => `"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([csv], { type:'text/csv' }));
  a.download = 'TestCases_Template.csv';
  a.click();
  URL.revokeObjectURL(a.href);
}

function handleTemplateCaseImport(input) {
  const file = input.files[0]; if (!file) return; input.value = '';
  file.text().then(text => {
    const rows = parseCSVGeneric(text);
    if (!rows.length) { toast('No data rows found in CSV', 'warn'); return; }
    const sectionMap = new Map();
    for (const r of rows) {
      const sTitle = (r.Section      || r.section      || '').trim();
      const proc   = (r.Procedure    || r.procedure    || r['Test Procedure'] || '').trim();
      const code   = (r.Code         || r.TestCaseCode || r['Test Case Code'] || '').trim();
      const name   = (r.Name         || r.TestName     || r['Test Case Name'] || '').trim();
      const scopeRaw = (r.Scope || r.scope || r.ScopeType || r['Scope Type'] || '').trim().toLowerCase();
      const scopeType = scopeRaw === 'dynamic' ? 'dynamic' : 'static';
      const assets  = (r.Assets       || r.assets       || '').trim();
      if (!code && !name) continue;
      const key = sTitle || '__default__';
      if (!sectionMap.has(key)) sectionMap.set(key, { title: sTitle, procedure: proc, cases: [] });
      const sec = sectionMap.get(key);
      if (!sec.procedure && proc) sec.procedure = proc;
      sec.cases.push({ code, name, scopeType, assets });
    }
    if (!sectionMap.size) { toast('Could not parse any test cases from CSV', 'warn'); return; }
    _templateSections = [...sectionMap.values()];
    const total = _templateSections.reduce((s, sec) => s + sec.cases.length, 0);
    document.getElementById('tpl-sections').innerHTML = _tplSectionsHTML();
    toast(`Imported ${total} test case${total !== 1 ? 's' : ''} across ${_templateSections.length} section${_templateSections.length !== 1 ? 's' : ''}`, 'success');
  });
}

// ── Shared modal body ─────────────────────────────────────────────────────────

function _tplModalBody() {
  return `
    <div class="form-grid" style="margin-bottom:20px;">
      <div class="form-field form-field-full">
        <label>Activity Name</label>
        <input type="text" id="tpl-name" class="form-input" placeholder="e.g. ATS LATS Hardware SAT">
      </div>
      <div class="form-field">
        <label>Subsystem</label>
        <select id="tpl-subsystem" class="form-input">
          ${SUBSYSTEMS_LIST.map(s => `<option>${escapeHtml(s)}</option>`).join('')}
        </select>
      </div>
      <div class="form-field form-field-full">
        <label>Description</label>
        <textarea id="tpl-desc" class="form-input" rows="2" placeholder="What does this activity cover?"></textarea>
      </div>
    </div>
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">
      <div style="font-weight:600;font-size:13px;">Sections &amp; Test Cases</div>
      <div style="display:flex;gap:8px;align-items:center;">
        <button class="form-secondary" style="font-size:12px;padding:5px 10px;" onclick="downloadTemplateCaseCSV()">↓ CSV Template</button>
        <label style="cursor:pointer;">
          <input type="file" accept=".csv" onchange="handleTemplateCaseImport(this)" style="display:none">
          <div class="form-secondary" style="font-size:12px;padding:5px 10px;cursor:pointer;display:inline-block;">${icon('folder')} Import CSV</div>
        </label>
      </div>
    </div>
    <div id="tpl-sections">${_tplSectionsHTML()}</div>
    <button class="form-secondary" style="width:100%;font-size:13px;border-style:dashed;margin-top:2px;"
      onclick="addTplSection()">+ Add Section</button>
    ${typeof _tplFormsBlockHTML === 'function' ? _tplFormsBlockHTML(_editTemplateId) : ''}
  `;
}

// ── Open modals ───────────────────────────────────────────────────────────────

function openNewTemplateModal() {
  _editTemplateId   = null;
  _templateSections = [{ title:'', procedure:'', cases:[{ code:'', name:'', scopeType:'static', assets:'' }] }];
  modal({
    title:  'Create Activity Template',
    sub:    'Define reusable test sections and procedures for an activity',
    size:   'large',
    body:   _tplModalBody(),
    footer: `<button class="form-secondary" onclick="closeModal()">Cancel</button>
             <button class="form-submit" onclick="saveNewTemplate()">Create Activity Template</button>`,
  });
}

async function saveNewTemplate() {
  if (typeof uiCan === 'function' && !uiCan('templates', 'create')) { toast('You do not have permission to create templates', 'error'); return; }
  const name      = document.getElementById('tpl-name')?.value.trim();
  const subsystem = document.getElementById('tpl-subsystem')?.value;
  const desc      = document.getElementById('tpl-desc')?.value.trim();
  if (!name) { toast('Activity Name is required', 'error'); return; }
  const testCases = _tplSectionsToTestCases(_templateSections);
  if (!testCases.length) { toast('Add at least one test case', 'error'); return; }
  const newTpl = {
    id: 'tpl-' + Date.now(), name, subsystem, description: desc,
    createdBy: currentRoleUser.name, createdAt: new Date().toISOString(), testCases,
  };
  const { error } = await _sb.from('templates').insert({
    id: newTpl.id, name: newTpl.name, subsystem: newTpl.subsystem,
    description: newTpl.description, created_by: newTpl.createdBy,
    created_at: newTpl.createdAt, test_cases: newTpl.testCases,
  });
  if (error) { toast('Save failed: ' + error.message, 'error'); return; }
  TEMPLATES.push(newTpl);
  logAudit('Created Activity Template', name, `${testCases.length} test cases`);
  closeModal();
  toast(`Created: ${name}`, 'success');
  renderAdminPortal();
  renderAdminTemplates();
}

function editTemplate(id) {
  const tpl = TEMPLATES.find(t => t.id === id);
  if (!tpl) return;
  _editTemplateId   = id;
  _templateSections = _tplCasesToSections(tpl.testCases);
  modal({
    title:  'Edit Activity Template',
    sub:    tpl.name,
    size:   'large',
    body:   _tplModalBody(),
    footer: `<button class="form-secondary" onclick="closeModal()">Cancel</button>
             <button class="form-submit" onclick="saveEditTemplate()">Save Changes</button>`,
  });
  setTimeout(() => {
    const el = (id) => document.getElementById(id);
    if (el('tpl-name'))      el('tpl-name').value      = tpl.name;
    if (el('tpl-subsystem')) el('tpl-subsystem').value  = tpl.subsystem || '';
    if (el('tpl-desc'))      el('tpl-desc').value       = tpl.description || '';
  }, 0);
}

async function saveEditTemplate() {
  if (typeof uiCan === 'function' && !uiCan('templates', 'edit')) { toast('You do not have permission to edit templates', 'error'); return; }
  const id  = _editTemplateId;
  const tpl = id ? TEMPLATES.find(t => t.id === id) : null;
  if (!tpl) { toast('Template not found', 'error'); return; }
  const name      = document.getElementById('tpl-name')?.value.trim();
  const subsystem = document.getElementById('tpl-subsystem')?.value;
  const desc      = document.getElementById('tpl-desc')?.value.trim();
  if (!name) { toast('Activity Name is required', 'error'); return; }
  const testCases = _tplSectionsToTestCases(_templateSections);
  if (!testCases.length) { toast('Add at least one test case', 'error'); return; }
  const btn = document.querySelector('.modal-footer .form-submit');
  if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }
  try {
    await _dbUpdate('templates', { name, subsystem, description: desc, test_cases: testCases }, { id });
    tpl.name = name; tpl.subsystem = subsystem; tpl.description = desc; tpl.testCases = testCases;
    logAudit('Edited Activity Template', name, `${testCases.length} test cases`);
    closeModal();
    toast(`Saved: ${name}`, 'success');
    renderAdminPortal();
    renderAdminTemplates();
  } catch(e) {
    toast('Save failed: ' + e.message, 'error');
    if (btn) { btn.disabled = false; btn.textContent = 'Save Changes'; }
  }
}

async function deleteTemplate(id) {
  if (typeof uiCan === 'function' && !uiCan('templates', 'delete')) { toast('You do not have permission to delete templates', 'error'); return; }
  const tpl = TEMPLATES.find(t => t.id === id);
  if (!tpl) return;
  const deployCount = DEPLOYMENTS.filter(d => d.templateId === id).length;
  const warn = deployCount > 0 ? ` This template has ${deployCount} active deployment(s).` : '';
  if (!await cxConfirm(`Delete template "${tpl.name}"?${warn}\n\nThis cannot be undone.`)) return;
  const { error } = await _sb.from('templates').delete().eq('id', id);
  if (error) { toast('Delete failed: ' + error.message, 'error'); return; }
  const idx = TEMPLATES.indexOf(tpl);
  TEMPLATES.splice(idx, 1);
  logAudit('Deleted Activity Template', tpl.name);
  toast(`Deleted: ${tpl.name}`, 'success');
  renderAdminPortal();
  renderAdminTemplates();
}

